(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c57"]=[{"id":"00011332","register_sub_id":"101","register_pk":"209169","name":"不破家住宅土蔵","kana":"ふわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町字上出2351","lat":35.234031,"lng":136.256813,"geo_status":"db","era":"嘉永6","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0381","desc":"主屋の東後方に南北棟で建つ。土蔵造二階建、桁行七・九メートル梁間五・〇メートル、置屋根式の切妻造桟瓦葺で西面南寄りの戸口に下屋を設け、扉枠に龍の鏝絵を飾る。外壁漆喰塗で軒先まで塗込め、置屋根の登梁鼻に絵様を表す。左官技法に見応えのある土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011332"},{"id":"00011333","register_sub_id":"101","register_pk":"209170","name":"不破家住宅門及び塀","kana":"ふわけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市高宮町字上出2351","lat":35.234183,"lng":136.256567,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口2.0m 塀 木造、瓦葺、総延長4.0m","structure_material":"門 木造","registered":"2016.11.29(平成28.11.29)","register_no":"25－0382","desc":"主屋の玄関正面で通り沿いに開く門と、左右にのびる塀。門は、間口二・〇メートルの腕木門、切妻造桟瓦葺で、潜り付の大戸を片引にたてる。塀は各々長さ二・〇メートルで表側を竪板張目板打とし、丸棒の目板瓦を葺く。宿場町の落ち着いた風情を醸している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011333"},{"id":"00000693","register_sub_id":"101","register_pk":"101683","name":"前田家住宅表門","kana":"まえだけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市土田町1191","lat":35.131025,"lng":136.08497361,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"煉瓦造，幅2.9m，高さ1.4m","structure_material":"煉瓦造","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0041","desc":"門柱上下の煉瓦の扱いや門扉のハツリ仕上げなど主屋の意匠と呼応するが，門柱の主体部はコンクリートの引っ掻き仕上げにハネた煉瓦をランダムに貼りつけ，主屋の外壁仕様との対比をみせている。一見素朴ながら随所に技巧を凝らした造形物になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000693"},{"id":"00000692","register_sub_id":"101","register_pk":"101682","name":"前田家住宅洋館","kana":"まえだけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市土田町1191","lat":35.13130289,"lng":136.08499964,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造２階建，瓦葺，建築面積175㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0040","desc":"ヴォーリズ事務所の建築部員であった佐藤久勝の自邸。スパニッシュを主調にスイスのコッテージ趣味を採り入れた住宅建築で，玄関の縁取りにみられる煉瓦タイルの扱いなど，事務所きっての名デザイナーといわれた佐藤久勝の手腕が遺憾なく発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000692"},{"id":"00000793","register_sub_id":"101","register_pk":"101783","name":"松本家住宅主屋","kana":"まつもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市上岸本町932","lat":35.1157545,"lng":136.23139484,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積109㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0051","desc":"前面に土間を取り奥側に居室部を配する平面になるが，正面左手奥の座敷及び右手前の台所を左右に配する変則的な構成になり，屋根も入母屋屋根を矩折れにかける。内部は，繊細な彫刻欄間など見るべきものがある。元別荘とつたえられる昭和初期の住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000793"},{"id":"00000794","register_sub_id":"101","register_pk":"101784","name":"松本家住宅土蔵","kana":"まつもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市上岸本町932","lat":35.11581764,"lng":136.23136326,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積20㎡","structure_material":"土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0052","desc":"主屋の右手背後に建つ切妻造，平入りの小規模な南北棟土蔵で，扉口を設ける西面に庇が付く。土蔵への出入りは，主屋背後から突出する物置側からとなる。建築年代は主屋と同時期といわれ，壁面は時代相応の人造石研出しとする。立ちが高い昭和期の土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000794"},{"id":"00013271","register_sub_id":"101","register_pk":"366260","name":"丸亀家住宅","kana":"まるがめけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市中央一丁目115-8","lat":35.00778056,"lng":135.86369167,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積41㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"25 － 0451","desc":"通りから小路を入った突当りに南面して建つ、二戸一棟の木造二階建長屋の東半部。間口二間強、奥行五間で、正面東寄りの玄関にガラス戸を建て、西側に出格子を作る。平面や正面は西隣に連なる別宅と同様だが、円形の下地窓や欄間などの意匠に相違も見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013271"},{"id":"00012168","register_sub_id":"101","register_pk":"352968","name":"南川家住宅主屋","kana":"みなみがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市森尻町2","lat":35.110349,"lng":136.07937,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積206㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"25-406","desc":"旧城下町南方の集落にあり、敷地中央に南面する。二階建の居室部と平屋建の座敷部からなる。居室部は中廊下式で、玄関と勝手口より合理的な動線が確保される。座敷部は四間取で、三方に縁を廻し開放的な造り。筬欄間や彫刻欄間など細部意匠に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012168"},{"id":"00012169","register_sub_id":"101","register_pk":"352969","name":"南川家住宅長屋門","kana":"みなみがわけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市森尻町2","lat":35.110279,"lng":136.079579,"geo_status":"db","era":"江戸末期／平成15年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-407","desc":"敷地東面を画する長屋門。中央部を一間幅の門口とし両開板扉を吊り、潜戸を付ける。北側の室は板敷で、南側の室は二室に仕切り、北側を板敷、南側を土間とする。外壁は腰板張で上部は漆喰塗とし、与力窓を開き、格式ある表構えで歴史的景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012169"},{"id":"00010316","register_sub_id":"101","register_pk":"199089","name":"宮本家住宅主屋","kana":"みやもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市音羽台字垣内212-2","lat":35.001864,"lng":135.860838,"geo_status":"db","era":"昭和5年／昭和10年頃・平成4年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"25-0354","desc":"スペイン瓦葺の木造二階建住宅。外壁スタッコ塗で縦長窓や半円アーチ窓を並べ煙突二本を設ける。内部は洋間主体で一部を和室とする。建物と調和が図られた建具や調度も保存良好で、居間のアルコーブや暖炉、緩やかな階段等にヴォーリズ建築の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010316"},{"id":"00009638","register_sub_id":"101","register_pk":"194634","name":"森家住宅主屋","kana":"もりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市芹町17","lat":35.26202179,"lng":136.25904602,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積66㎡","structure_material":"木造平屋一部2階建","registered":"2013.06.21(平成25.06.21)","register_no":"25 － 0346","desc":"通りに南面するつし二階建の町家で、正面を黒漆喰で塗込めて虫籠窓を穿ち、両袖に漆喰で縁取りした袖うだつを設け、軒先やけらばも漆喰仕上げとする。内部は東に土間玄関を配し、居室部は手前からミセノマなどを並べる。丁寧なつくりになる彦根城下の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009638"},{"id":"00008713","register_sub_id":"101","register_pk":"149434","name":"森本家住宅主屋","kana":"もりもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市浜町33-1","lat":35.00860122,"lng":135.86711435,"geo_status":"db","era":"嘉永2年(1849)／昭和前期改修","year":1849,"year_source":"converted","year_min":1849,"year_max":1849,"year_label":null,"structure":"木造2階建、瓦葺、建築面積184㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"25 － 0296","desc":"浜通りに南面する敷地に建つ。桁行9.0ｍ梁間16ｍの木造2階建で背面に角屋を付設。切妻造桟瓦葺で、越屋根を置く。西を通りニワとする1列4室を基本にする大規模な町家で、上昇感の強いニワは印象的。小路に面する西妻の漆喰大壁が景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008713"},{"id":"00008714","register_sub_id":"101","register_pk":"149435","name":"森本家住宅門塀","kana":"もりもとけじゅうたくもんべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市浜町33-1","lat":35.00852308,"lng":135.86704296,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、総延長17m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"25 － 0297","desc":"角地を囲むように建つ。総延長17ｍ。浜通り側が塀瓦葺の高塀で、上部を漆喰壁、腰を竪板張とする。西寄りを1ｍほど控え、中央に1.4ｍの門口を設け、前後に桟瓦葺庇をかける。小路側は棟を銅板覆いの高板塀。穏やかで、品格ある屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008714"},{"id":"00014047","register_sub_id":"101","register_pk":"508307","name":"山本家住宅主屋","kana":"やまもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県米原市柏原字市場町961","lat":35.34343611,"lng":136.40127222,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積243㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0497","desc":"旧中山道沿いに前庭を配し南面する住宅。切妻造平入桟瓦葺、中央の二列六室を挟んで、西に土間、東に式台と玄関を配す。式台は入母屋造屋根を付し三面をガラス戸とする。玄関は吹抜の土間で、内装をハーフティンバーとし暖炉を設えて洋風とした近代の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014047"},{"id":"00000983","register_sub_id":"101","register_pk":"101973","name":"吉田悦藏家住宅茶室","kana":"よしだえつぞうけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市池田町5-21-3","lat":35.13477001,"lng":136.08810364,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積43㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0106","desc":"洋館の左手に位置する「離れ」的な建物で，八畳大の床付き座敷を中核として，北に土間，西に四畳大の茶室，南の水屋をはりだす。吉田悦藏自身の設計と伝えられ，住居の成長・発展を物語る遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000983"},{"id":"00011340","register_sub_id":"101","register_pk":"209177","name":"若林家住宅北土蔵","kana":"わかばやしけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県彦根市犬方町758","lat":35.234276,"lng":136.244089,"geo_status":"db","era":"大正9／昭和3移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0389","desc":"敷地北東隅に南北棟で建つ。土蔵造二階建、桁行七・九メートル、梁間四・九メートル、切妻造桟瓦葺で西面南寄りに戸口を開く。外壁漆喰塗で鉢巻を廻らし、両妻面の小窓に、絵様を象る鳥居枠を作る。洋室棟と並び建つ風格ある土蔵で、屋敷角地の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011340"},{"id":"00011338","register_sub_id":"101","register_pk":"209175","name":"若林家住宅座敷棟","kana":"わかばやしけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県彦根市犬方町758","lat":35.234094,"lng":136.243825,"geo_status":"db","era":"大正13／昭和3移築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0387","desc":"主屋西側に接続する入母屋造桟瓦葺で、西端部を落棟とし、下屋を廻らす。一二畳半主室と一〇畳を並べて周囲を廊下で囲み、南北の庭を望む。主室西面に床と、天袋付の清楼棚、付書院を備え、室境に繊細な意匠の透彫欄間を入れる。上質で気品を備えた座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011338"},{"id":"00011335","register_sub_id":"101","register_pk":"209172","name":"若林家住宅主屋","kana":"わかばやしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市犬方町758","lat":35.234131,"lng":136.243937,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積117㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0384","desc":"広大な敷地の中央北寄りに建つ二階建、入母屋造桟瓦葺。北面に玄関を構え、南東に台所棟、西に座敷棟を雁行させる。八畳西面に大振りの花頭窓を穿つなど大胆な意匠の座敷飾を備え、縁に大判ガラスの窓をたてる。豪奢かつ上質な意匠になる大型の近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011335"},{"id":"00011337","register_sub_id":"101","register_pk":"209174","name":"若林家住宅台所棟","kana":"わかばやしけじゅうたくだいどころとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市犬方町758","lat":35.234131,"lng":136.244054,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0386","desc":"主屋南東に雁行して建ち、西面屋根を破風を重ねた入母屋造、東面を切妻造とする桟瓦葺で、下屋を廻らし、周囲にガラス窓をたてる。夫人室と台所、風呂などからなり、夫人室の天井の一部を掛込天井とし、三角平面の釣床を備えるなど闊達な数寄屋意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011337"},{"id":"00011339","register_sub_id":"101","register_pk":"209176","name":"若林家住宅茶室棟","kana":"わかばやしけじゅうたくちゃしつとう","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県彦根市犬方町758","lat":35.234005,"lng":136.24376,"geo_status":"db","era":"大正13／昭和3移築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0388","desc":"座敷棟南西に雁行し、南面入母屋造、北面切妻造とする桟瓦葺で、軒先を銅板葺とする。四畳半茶室と三畳の南・東面に縁を廻らす構成で、茶室西面の一間半の床は、落掛に竹を使う原叟床風の構えに袖壁を付す。縁の軒は小丸太を扇に配り、深い軒を軽快に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011339"},{"id":"00011341","register_sub_id":"101","register_pk":"209178","name":"若林家住宅南土蔵","kana":"わかばやしけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県彦根市犬方町758","lat":35.234199,"lng":136.244134,"geo_status":"db","era":"大正9／昭和3移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0390","desc":"敷地東辺、北土蔵の南に連なり南北棟で建つ。土蔵造二階建、桁行六・九メートル、梁間四・九メートル、切妻造桟瓦葺で西面北寄りに戸口を開く。外壁漆喰塗で鉢巻と水切を廻らし、西・北面に小窓を配する。北土蔵とともに、重厚な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011341"},{"id":"00011342","register_sub_id":"101","register_pk":"209179","name":"若林家住宅門及び塀","kana":"わかばやしけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市犬方町758","lat":35.23426198,"lng":136.24386989,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口3.0m 塀 木造、瓦葺、総延長68m","structure_material":"門 木造","registered":"2016.11.29(平成28.11.29)","register_no":"25－0391","desc":"主屋の玄関正面に、通りから奥まって開く門と東西に矩折れにのびる塀。門は間口三・〇メートルの高塀に腕木門を取込む形式で前後に桟瓦葺の庇を付し、格子戸引分けとする。塀は腰を竪板張、壁を中塗仕上として一間おきに小窓を穿つ。良質な街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011342"},{"id":"00011336","register_sub_id":"101","register_pk":"209173","name":"若林家住宅洋室棟","kana":"わかばやしけじゅうたくようしつとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市犬方町758","lat":35.234205,"lng":136.243999,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積28㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"25－0385","desc":"主屋北東隅に接続する南北棟の二階建。赤色瓦の半切妻屋根に煙突を立て、外壁を人造石洗出しとする。内部は上下階とも洋室一室で、一階応接室では暖炉や腰掛付出窓などにチューダー様式を取入れ、天井のレリーフを彩色で飾る。洗練された意匠の接客棟である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011336"},{"id":"00000301","register_sub_id":"101","register_pk":"101291","name":"青山ビル","kana":"あおやまびる","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区伏見町2-2-6","lat":34.68895018,"lng":135.50608947,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造地上5階地下１階建，建築面積258㎡","structure_material":"鉄筋コンクリート造地上5階地下１階建","registered":"1997.09.03(平成9.09.03)","register_no":"27 － 0024","desc":"鉄筋コンクリート造，地上５階地下１階建で，当初は１・２階を住宅，３階以上を貸室としていた。中層の都市住宅としては初期の事例のひとつであり，要所に装飾を配した外観や瀟洒な意匠の階段等に時代の特徴がよく表れている。設計は伊東恒治。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000301"},{"id":"00006225","register_sub_id":"101","register_pk":"107209","name":"赤石家住宅座敷蔵","kana":"あかいしけじゅうたくざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字森屋911-乙","lat":34.469097,"lng":135.62167224,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積51㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0422","desc":"主屋南面に接してほぼ直角方向に建つ。桁行６間，梁間２間半の切妻造，桟瓦葺，平入の木造２階建で，たちが高い。外壁を真壁造，１階腰を板壁，上部を漆喰塗とし，安定感のある意匠とする。２階平側に引違ガラス戸を連続して設け，近代的な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006225"},{"id":"00006224","register_sub_id":"101","register_pk":"107208","name":"赤石家住宅主屋","kana":"あかいしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字森屋911-乙","lat":34.469204,"lng":135.621628,"geo_status":"db","era":"明治14","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0421","desc":"村の中心地に位置する農家建築。桁行９間半，梁間５間規模の入母屋造，桟瓦葺，木造つし２階建で，西端に越屋根を設ける。平面は整形６間取でヒロシキを設ける。外壁に黒漆喰を用い，虫籠窓を設けるなど重厚なつくりで，規模も大きく，集落景観の形成に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006224"},{"id":"00004377","register_sub_id":"101","register_pk":"105367","name":"浅野家住宅乾蔵","kana":"あさのけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市久宝寺五丁目69","lat":34.6267406,"lng":135.58632787,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0305","desc":"主屋の西，敷地の北西角に位置する桁行２間梁間２間規模の土蔵造２階建である。屋根は切妻造，本瓦葺とする。外壁は白漆喰塗で，腰を縦羽目板張としている。東面に戸口を設けて片引の土戸を建て込み，２階南面に窓を開く。北面の門と塀は近年の改修である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004377"},{"id":"00004376","register_sub_id":"101","register_pk":"105366","name":"浅野家住宅主屋","kana":"あさのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市久宝寺五丁目69","lat":34.62672045,"lng":135.58647769,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0304","desc":"街路に北面して建つ。桁行７間梁行５間のつし２階建で，屋根は切妻造，本瓦葺とし，表に桟瓦葺の庇がつく。平入で桁行の半分が土間とし，四間取の居室をもつ農家系の平面である。正面は大戸廻りを改修したほかは１階出格子と２階虫籠窓等が良好に遺存する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004376"},{"id":"00004378","register_sub_id":"101","register_pk":"105368","name":"浅野家住宅巽蔵","kana":"あさのけじゅうたくたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府八尾市久宝寺五丁目69","lat":34.62651439,"lng":135.58654976,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0306","desc":"敷地の南東隅に位置する桁行２間半梁間２間の土蔵造２階建で，屋根は南北棟，切妻造，桟瓦葺とする。外壁は白漆喰塗で，腰を縦羽目板張とする。西面に戸口を設け，北に接続する納屋から一連の瓦葺庇をかける。２階妻面には唐破風形の小庇をつけた円窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004378"},{"id":"00004379","register_sub_id":"101","register_pk":"105369","name":"浅野家住宅東納屋","kana":"あさのけじゅうたくひがしなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府八尾市久宝寺五丁目69","lat":34.62659851,"lng":135.58655589,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0307","desc":"主屋の南背後，敷地の東辺に沿って建つ桁行３間半梁間２間の木造平屋建で巽蔵の北に接続。屋根は切妻造，本瓦葺で，西面の桟瓦葺の庇は巽蔵の蔵前まで一連に造る。外壁は白漆喰塗で腰を縦羽目板張とする。北に落ち棟で桁行２間，梁間１間半の平屋建が続く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004379"},{"id":"00004380","register_sub_id":"101","register_pk":"105370","name":"浅野家住宅南納屋","kana":"あさのけじゅうたくみなみなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府八尾市久宝寺五丁目69","lat":34.62651045,"lng":135.58643269,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0308","desc":"敷地の南辺中央，巽蔵の西に位置する木造平屋建である。桁行２間半梁間１間半の東西棟で，屋根は切妻造，桟瓦葺とする。外壁は土壁で腰を縦羽目板張とする。庭に面した北面に戸口を設け，妻にガラス窓を開けている。敷地南からの景観の一要素をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004380"},{"id":"00001201","register_sub_id":"101","register_pk":"102191","name":"新井家住宅奥座敷","kana":"あらいけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市中庄1380","lat":34.409061,"lng":135.329071,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積120㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"27 － 0067","desc":"コの字型構成になる本邸の左翼部にあたる。平面は上段の間が附属する１５畳大の座敷と１０畳大の次の間を中心とした構成になる。内法の高い座敷の廻りに畳廊下及び縁を設け、ゆったりと園を見渡せるように工夫する。全体に質の高い技巧的な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001201"},{"id":"00001203","register_sub_id":"101","register_pk":"102193","name":"新井家住宅蔵","kana":"あらいけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市中庄1380","lat":34.40873617,"lng":135.32920496,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積126㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"27 － 0069","desc":"住宅棟の南側に建つ切妻造、本瓦葺の２階建の大型土蔵。家財や什器類を納める内向きの蔵で、主屋とは廊下で結ばれる。外観は標準的な意匠で、一階部分をなまこ壁仕上げとする。大正から昭和期にかけての家人の生活を知る上でも、重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001203"},{"id":"00001200","register_sub_id":"101","register_pk":"102190","name":"新井家住宅玄関・座敷","kana":"あらいけじゅうたくげんかん・ざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市中庄1380","lat":34.40905245,"lng":135.32924066,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積181㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"27 － 0066","desc":"居宅と迎賓館を兼ねた豪華な本邸を構成する建物の一つ。小高い丘陵上の広大な敷地に建ち、和風庭園に囲まれたコの字型構成の中央部を占める。玄関の奥に南及び東面に畳廊下と縁を配した上質の座敷が続く。玄関、座敷とも本瓦葺で、重厚な佇まいになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001200"},{"id":"00001202","register_sub_id":"101","register_pk":"102192","name":"新井家住宅主屋","kana":"あらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市中庄1380","lat":34.40883697,"lng":135.32926907,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積329㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"27 － 0068","desc":"コの字型構成の右翼部にあたる。平面は、前庭に面して玄関口を設け、南側に６畳３室及び４畳半の居室が縦長に並ぶ。中庭を挟んで北側に８畳間・風呂・便所などを置き、東北側には食堂及び接客を賄う２１畳大の広い炊事場を設けるなど独特の構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001202"},{"id":"00001205","register_sub_id":"101","register_pk":"102195","name":"新井家住宅塀","kana":"あらいけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市中庄1380","lat":34.40897734,"lng":135.32892305,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土塀，瓦葺，延長130m","structure_material":"土塀","registered":"1999.07.08(平成11.07.08)","register_no":"27 － 0071","desc":"屋敷地の西辺部を画する土塀で、表門を挟んでその両側に設けられる。切石積の基礎上に建ち、漆喰仕上げ、瓦葺とする本格的な造りになる。総延長１３０ｍに及び、「新井の別邸」として知られる豪華な住宅にふさわしい堂々とした土塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001205"},{"id":"00001204","register_sub_id":"101","register_pk":"102194","name":"新井家住宅門","kana":"あらいけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市中庄1380","lat":34.40887738,"lng":135.3290441,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造薬医門，瓦葺，建築面積32㎡","structure_material":"木造薬医門","registered":"1999.07.08(平成11.07.08)","register_no":"27 － 0070","desc":"敷地南西部のやや屈曲した道路に面して建つ大型の三間の薬医門。道路面からやや引き込んだ位置にあり、両側に袖塀が付く。全体として木柄が太く、屋根を本瓦葺とした重厚な構えは、豪華な本邸にふさわしい堂々とした風格を保つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001204"},{"id":"00002559","register_sub_id":"101","register_pk":"103549","name":"池永家住宅内蔵","kana":"いけながけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市西淀川区野里1-26-8","lat":34.71179354,"lng":135.46276018,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"27 － 0161","desc":"主屋の北東部に建つ土蔵で，現在は主屋増築部とつながり，現在も家財等の収納に用いられている。切妻造・妻入の２階建で，南妻面に観音扉を設け，屋根は東西棟・桟瓦葺，外壁は白漆喰塗と縦板張を併用する。屋敷の構成要素として欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002559"},{"id":"00002560","register_sub_id":"101","register_pk":"103550","name":"池永家住宅米蔵・道具蔵","kana":"いけながけじゅうたくこめぐら・どうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西淀川区野里1-26-8","lat":34.711887,"lng":135.462723,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"27 － 0162","desc":"離れとほぼ同時の建築で，その北側に独立して建つ。切妻造・平入の２階建で，屋根は南北棟・本瓦葺である。内部は北１間半分が米蔵，南２間分が道具蔵にそれぞれ用いられ，これに応じて東面に２つの観音扉を設ける。豪農の屋敷構成上，欠かせない附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002560"},{"id":"00002556","register_sub_id":"101","register_pk":"103546","name":"池永家住宅主屋","kana":"いけながけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市西淀川区野里1-26-8","lat":34.7118834,"lng":135.46287919,"geo_status":"db","era":"江戸中期／明治中期改造","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積161㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"27 － 0158","desc":"大阪市北西部，淀川河口付近にある豪農の家柄で，主屋は１８世紀中期頃を骨格とし，文化年間の増改築を経て明治中期に現在の形となった。柱や土間の梁組など古民家の要素をよく残し，桟瓦葺・２階建の雄大な外観は，今なおかつての農村景観を彷彿とさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002556"},{"id":"00002557","register_sub_id":"101","register_pk":"103547","name":"池永家住宅長屋門","kana":"いけながけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市西淀川区野里1-26-8","lat":34.7117193,"lng":135.46289932,"geo_status":"db","era":"弘化3","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"27 － 0159","desc":"長方形の屋敷地南面に建つ東西に細長い建物で，桟瓦葺屋根は東側が入母屋造，西側が切妻造になり，中央は通路土間，その左右をそれぞれ部屋とする。切石積基礎で，腰を縦板張，上部を砂漆喰壁とし，東西に連続する高塀とともに屋敷の表構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002557"},{"id":"00002558","register_sub_id":"101","register_pk":"103548","name":"池永家住宅離れ","kana":"いけながけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西淀川区野里1-26-8","lat":34.71181624,"lng":135.46279992,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"27 － 0160","desc":"屋敷地の西，主屋西側に並立して建ち，通路で連続する。切妻造，桟瓦葺，平入で，内部は床・床脇を備えた数寄屋風意匠でまとめられ，小壁の板欄間など繊細である。現在は旧野里村に伝わる歴史資料を展示した郷土資料館として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002558"},{"id":"00014493","register_sub_id":"101","register_pk":"513907","name":"石川家住宅主屋","kana":"いしかわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目120-１","lat":34.67014444,"lng":135.56121667,"geo_status":"db","era":"江戸末期／昭和前期・同50年代・平成27年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積178㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0864","desc":"菅笠産地で知られる旧深江村の旧家の主屋。座敷側を入母屋造、土間側を落棟とする桟瓦葺平入のつし二階建。床上は田の字の農家型平面で土間に板敷を張り出す。当初の土間は広大で、梁の木柄太く豪壮。仏間座敷に吊り仏壇を備え、洪水に備える地域色を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014493"},{"id":"00014494","register_sub_id":"101","register_pk":"513908","name":"石川家住宅段蔵","kana":"いしかわけじゅうたくだんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目120-１","lat":34.67030556,"lng":135.56107778,"geo_status":"db","era":"明治22年頃／大正後期・平成28年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0865","desc":"旧深江村の旧家の土蔵で敷地北西隅に位置する乾蔵。切妻造妻入本瓦葺の土蔵造二階建で腰板張。各階一室板敷、小屋組は規模の割に太い曲り梁を架ける。高石垣に建つ段蔵と呼ぶ形式で洪水に備えた建築。石垣は切石積、出隅は算木積で反りを持たせた丁寧な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014494"},{"id":"00014495","register_sub_id":"101","register_pk":"513909","name":"石川家住宅道具蔵","kana":"いしかわけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目120-１","lat":34.67025278,"lng":135.56107778,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積16㎡、塀付","structure_material":"土蔵造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0866","desc":"旧深江村の旧家の敷地西辺北寄りに位置する土蔵。切妻造平入本瓦葺、土蔵造二階建で腰板張。主屋側に庇と裏白戸を配す。各階一室板敷。北隣の段蔵と対照的に平地の土蔵で用途の違いが窺える。南北に土塀を連ね、屋敷構え外郭を構成し歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014495"},{"id":"00014496","register_sub_id":"101","register_pk":"513910","name":"石川家住宅長屋門","kana":"いしかわけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目120-１","lat":34.66994167,"lng":135.56129444,"geo_status":"db","era":"明治22年頃／昭和前期・同45年頃改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡ 南土塀付","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0867","desc":"旧深江村の旧家の敷地南辺に開く長屋門。切妻造平入桟瓦葺の平屋建。真壁造腰板張、門部分は出桁で袖部屋と一体で屋根を架け、木柄太い大戸と格子戸を建てる。袖部屋は通りに出格子窓を開ける。西側漆喰仕上土塀や東側付属屋と共に屋敷の表構えとなる長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014496"},{"id":"00014497","register_sub_id":"101","register_pk":"513911","name":"石川家住宅南西塀","kana":"いしかわけじゅうたくなんせいべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目120-１","lat":34.6701,"lng":135.56105278,"geo_status":"db","era":"明治22年頃","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土塀、瓦葺、延長41m","structure_material":"土塀","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0868","desc":"旧深江村旧家の敷地南・西辺を巡る土塀。東は長屋門西の土蔵跡から、南西角を隅切り、北に延びて主屋西の別棟座敷跡まで、延長四一メートル、瓦葺、蛇腹付の漆喰仕上で腰洗出し仕上。西辺に切石の方立と楣で両開き板戸の勝手口を開ける。歴史的景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014497"},{"id":"00014498","register_sub_id":"101","register_pk":"513912","name":"石川家住宅北東塀","kana":"いしかわけじゅうたくほくとうべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目120-１","lat":34.67026944,"lng":135.56138333,"geo_status":"db","era":"明治22年頃／昭和前期改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造、瓦葺、延長29m","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0869","desc":"旧深江村にある旧家の敷地北・東辺の塀。北辺土蔵から北東隅矩折れ、東辺主屋北東隅まで巡る。桟瓦葺、真壁造腰板張、北辺は高さ２・１メートルで勝手口と切石控えを設ける、東辺は高さ１・７メートル、元は１間おきに欄間を設けた。歴史的な街路空間を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014498"},{"id":"00006027","register_sub_id":"101","register_pk":"107012","name":"和泉市久保惣記念美術館茶室外腰掛待合","kana":"いずみしくぼそうきねんかんちゃしつそとこしかけまちあい","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.446648,"lng":135.452927,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0406","desc":"正門の北側に位置する。桁行２間半，梁間１間半規模，木造平屋建で，銅板葺，切妻造とする。北側は開放で腰掛とし，南側に物入を設ける。腰掛東側の下地窓には力竹を設けるなど，丁寧なつくり。聴泉亭に至る外露地の空間を形成し，豊かな景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006027"},{"id":"00006031","register_sub_id":"101","register_pk":"107016","name":"和泉市久保惣記念美術館茶室井筒","kana":"いずみしくぼそうきねんびじゅつかんちゃしついづつ","category":"住宅","subcategory":"その他工作物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.446827,"lng":135.453079,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造、面積0.49㎡","structure_material":"石造","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0411","desc":"梅見門の東方，聴泉亭の外露地に位置する。４個の御影石の自然石を組み，７０ｃｍ四方の井筒を形成する。深さは５０ｃｍ程度とし，井戸としての機能は持たない。表千家残月亭の外露地にある井戸の配置を模倣したもので，外露地の空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006031"},{"id":"00006028","register_sub_id":"101","register_pk":"107013","name":"和泉市久保惣記念美術館茶室内腰掛待合","kana":"いずみしくぼそうきねんびじゅつかんちゃしつうちこしかけまちあい","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.44690069,"lng":135.45299609,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.2㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0407","desc":"梅見門の東側に位置する。桁行１間半，梁間１間規模，木造平屋建で，銅板葺，切妻造とする。西側は開放で腰掛とし，東側に雪隠を設ける。腰掛南側には力竹を用いた下地窓を設け，北側は壁上部を吹放しとする。惣庵に至る内露地の空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006028"},{"id":"00006030","register_sub_id":"101","register_pk":"107015","name":"和泉市久保惣記念美術館茶室梅見門","kana":"いずみしくぼそうきねんびじゅつかんちゃしつうめみもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.446812,"lng":135.452972,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、銅板葺、間口1.0m","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0410","desc":"聴泉亭の外露地と惣庵の内露地の間に位置し，南面して建つ。間口１．０ｍ，銅板葺，切妻造の腕木門とする。柱は丸太を用い，竹格子戸を両開きとし，楣上部は吹放しとする。表千家残月亭の梅見門を写して，茶席の露地の空間を形成し，簡素であるが貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006030"},{"id":"00016553","register_sub_id":"101","register_pk":"574915","name":"和泉市久保惣記念美術館茶室北板塀","kana":"いずみしくぼそうきねんびじゅつかんちゃしつきたいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町三丁目6-12","lat":34.44595972,"lng":135.45323778,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、延長5.7m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0961","desc":"西蔵及び東蔵が位置する区画を仕切り、東西に延びる板塀。延長５・７メートルで中央部に両開き板扉を建てる。壁面は杉皮張で竹押縁で留め、欄間は丸竹を横に渡し、屋根に雁振瓦を載せる。茶室群の奥に位置する侘びた風情の塀で、敷地の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016553"},{"id":"00006026","register_sub_id":"101","register_pk":"107011","name":"和泉市久保惣記念美術館茶室玄関","kana":"いずみしくぼそうきねんびじゅつかんちゃしつげんかん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.446655,"lng":135.452835,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0402","desc":"敷地の南西方に位置し，東面して建つ。桁行５間，梁間４間半規模の木造平屋建で，東側に便所棟が付く。玄関は妻入で，銅板葺の庇を設け，竹簀の子の踏込みを備える。屋根は桟瓦葺で，軒先と螻羽は銅板葺とし，軽快な切妻屋根を見せ，敷地の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006026"},{"id":"00006000","register_sub_id":"101","register_pk":"106985","name":"和泉市久保惣記念美術館茶室楠蔭庵","kana":"いずみしくぼそうきねんびじゅつかんちゃしつしょういんあん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.446491,"lng":135.453125,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0405","desc":"正門の前に架かる太鼓橋の袂に位置する。桁行１間半，梁間２間半規模の木造平屋建で，貴人口を設けた３畳半の小間と２畳の水屋ノ間からなる。桟瓦葺，切妻造で，西面妻側を落ち棟とし，さらに銅板葺の土庇を出し，変化に富んだ屋根で敷地の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006000"},{"id":"00006025","register_sub_id":"101","register_pk":"107010","name":"和泉市久保惣記念美術館茶室正門","kana":"いずみしくぼそうきねんびじゅつかんちゃしつせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.446598,"lng":135.452942,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0408","desc":"敷地の南東隅に位置し，太鼓橋の前方に東面して建つ。間口２．１ｍの腕木門で，切妻造，桟瓦葺とし，軒先や螻羽は檜皮葺とする。扉は縦連子を入れた両開戸で，楣は丸太材を用い，上部は吹放しとするなど，簡素ながら丁寧なつくりとし，表の構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006025"},{"id":"00005999","register_sub_id":"101","register_pk":"106984","name":"和泉市久保惣記念美術館茶室惣庵","kana":"いずみしくぼそうきねんびじゅつかんちゃしつそうあん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.44685,"lng":135.452881,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0404","desc":"桁行２間，梁間３間規模の木造平屋建で，切妻造，桟瓦葺とし，銅板葺の庇が付く。３畳台目の小間と聴泉亭の北側に繋がる水屋からなる。東側の躙口正面に床と給仕口を設け，点前座の奥に茶道口を開く。化粧屋根裏の突上窓等，表千家不審庵を写す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005999"},{"id":"00005998","register_sub_id":"101","register_pk":"106983","name":"和泉市久保惣記念美術館茶室聴泉亭","kana":"いずみしくぼそうきねんびじゅつかんちゃしつちょうせんてい","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.446781,"lng":135.452881,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0403","desc":"敷地の中央西寄りに位置する。桁行３間，梁間７間規模の木造平屋建で，切妻造，桟瓦葺とし，東面妻側に銅板葺の庇を付ける。１０畳の座敷には，床の間として用いる２畳の上段や，付書院を設ける。寸法や各柱の材料等，表千家残月亭を写す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005998"},{"id":"00006029","register_sub_id":"101","register_pk":"107014","name":"和泉市久保惣記念美術館茶室中潜","kana":"いずみしくぼそうきねんびじゅつかんちゃしつなかくぐり","category":"住宅","subcategory":"その他工作物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町3-6-12","lat":34.446728,"lng":135.453033,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、銅板葺、延長2.7m","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0409","desc":"外腰掛待合の北方に位置し，南面して建つ。屋根は銅板葺，切妻造で，腕木を出し，竹垂木を配する。延長２．７ｍで塀のような形状とし，東側に引戸を付けた潜を設け，西側に力竹を用いた下地窓を開く。表千家残月亭の中潜を写し，外露地の空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006029"},{"id":"00016551","register_sub_id":"101","register_pk":"574913","name":"和泉市久保惣記念美術館茶室西蔵","kana":"いずみしくぼそうきねんびじゅつかんちゃしつにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町三丁目6-12","lat":34.44595972,"lng":135.45323778,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡、煉瓦塀付","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0959","desc":"敷地北西隅に位置する茶道具の収納蔵。土蔵造二階建切妻造平入桟瓦葺で、外壁は漆喰塗仕上、腰は黒漆喰塗仕上で水切を廻らす。各階板敷の一室で収納用の棚を設え、小屋組はキングポスト・トラス。戸口に鉄扉を吊り、重厚な外観で敷地奥の景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016551"},{"id":"00016555","register_sub_id":"101","register_pk":"574917","name":"和泉市久保惣記念美術館茶室西門","kana":"いずみしくぼそうきねんびじゅつかんちゃしつにしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町三丁目6-12","lat":34.44595972,"lng":135.45323778,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、間口1.7m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0963","desc":"敷地西辺の南端部に位置し、通りに西面して建つ通用門。石段上に建つ、切妻造平入桟瓦葺の腕木門で、背面両側に控柱を立てて貫で固める。門口に吊る両開きの板戸は、両面をなぐり仕上とした丁寧なつくり。簡素ながらも瀟洒な外観で敷地西辺の景観をつくる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016555"},{"id":"00016552","register_sub_id":"101","register_pk":"574914","name":"和泉市久保惣記念美術館茶室東蔵","kana":"いずみしくぼそうきねんびじゅつかんちゃしつひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町三丁目6-12","lat":34.44595972,"lng":135.45323778,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡、煉瓦塀付","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0960","desc":"敷地北側中央に位置する茶道具の収納蔵。土蔵造二階建切妻造平入桟瓦葺で外壁は漆喰塗、腰は海鼠壁仕上。戸口の楣に波に兎の鏝絵を飾り、波涛文を彫った持送で庇を支持する。小屋組はキングポスト・トラス。西蔵と並び建ち、歴史的な景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016552"},{"id":"00016556","register_sub_id":"101","register_pk":"574918","name":"和泉市久保惣記念美術館茶室南塀","kana":"いずみしくぼそうきねんびじゅつかんちゃしつみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町三丁目6-12","lat":34.44595972,"lng":135.45323778,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"煉瓦造、瓦葺、延長15m","structure_material":"煉瓦造","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0964","desc":"敷地の南辺を画する塀。延長一五メートル、切石積の基礎に建つ煉瓦塀で屋根桟瓦葺とする。壁はモルタル仕上で軒蛇腹を廻らし、内側は鎧状に３段の見切を付し、櫛引仕上とする。敷地南辺に延びる瀟洒なつくりの塀で、広大な庭園と一体で歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016556"},{"id":"00016554","register_sub_id":"101","register_pk":"574916","name":"和泉市久保惣記念美術館茶室露地門","kana":"いずみしくぼそうきねんびじゅつかんちゃしつろじもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市内田町三丁目6-12","lat":34.44595972,"lng":135.45323778,"geo_status":"db","era":"昭和12年／昭和56年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、建築面積2.3㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0962","desc":"正門と外腰掛待合の間に位置し、露地への入口に建つ門。屋根は目板瓦葺とし、門口に潜戸付板戸を開け、銅板葺の庇を付す。背面は銅板葺の下屋を葺き降ろし、内部は石敷の土間とする。塀に下屋を付した特徴的な平面で、表千家の露地門に通じる形式とした門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016554"},{"id":"00015038","register_sub_id":"101","register_pk":"529316","name":"市川家住宅（旧亀岡家別荘）表門及び塀","kana":"いちかわけじゅうたく（きゅうおかめおかけべっそう）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区帝塚山西四丁目84-1他","lat":34.61713333,"lng":135.495625,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"表門 木造、瓦葺一部銅板葺、間口1.5m、左右袖塀付 塀 木造、瓦葺、総延長15m","structure_material":"表門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0909","desc":"敷地西、土蔵の南に建つ表門と塀。表門は通りから引込み東面する腕木門。屋根上部に目板瓦葺の高塀を付した特徴的な外観で、両開板扉の戸口前面に引違格子戸を建てる。両袖塀は銅板葺の庇を掛け北脇に通用門を開く。両脇前方に取付く塀とともに表構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015038"},{"id":"00015036","register_sub_id":"101","register_pk":"529314","name":"市川家住宅（旧亀岡家別荘）主屋","kana":"いちかわけじゅうたく（きゅうおかめおかけべっそう）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区帝塚山西四丁目84-1他","lat":34.61714722,"lng":135.495825,"geo_status":"db","era":"大正後期／平成元年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺一部銅板葺、建築面積207㎡、渡廊下付","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0907","desc":"船場の実業家の別荘主屋。二階建桟瓦葺で全体に和風を基調としつつ、南と西の庭に面する座敷は、床構えなど用材と意匠に凝ったつくり。二階南西隅はマントルピース付洋室とし、白色塗の外壁に上下窓、緩いアーチ形の小壁で飾るベランダなど外観が目を惹く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015036"},{"id":"00015039","register_sub_id":"101","register_pk":"529317","name":"市川家住宅（旧亀岡家別荘）北中門及び待合","kana":"いちかわけじゅうたく（きゅうおかめおかけべっそう）きたちゅうもんおよびまちあい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区帝塚山西四丁目84-1他","lat":34.61714444,"lng":135.49571389,"geo_status":"db","era":"大正後期／昭和後期改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"中門 木造、瓦葺一部銅板葺、間口1.2m 待合 木造平屋建、瓦葺一部銅板葺、建築面積0.8㎡","structure_material":"中門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0910","desc":"主屋玄関への苑路と北の中庭を画す北中門と待合。南面する北中門は柱や棟木、桁に出節丸太、冠木にサクラの皮付丸太、軒裏に杉皮を用い、門扉は格子戸で上部に格狭間を飾る。西脇に接続する待合も柱に出節丸太、両脇壁に下地窓を開くなど凝ったつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015039"},{"id":"00015037","register_sub_id":"101","register_pk":"529315","name":"市川家住宅（旧亀岡家別荘）土蔵","kana":"いちかわけじゅうたく（きゅうおかめおかけべっそう）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市住吉区帝塚山西四丁目84-1他","lat":34.61718056,"lng":135.49563056,"geo_status":"db","era":"大正後期／昭和63年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0908","desc":"主屋の西に建つかつての家財蔵。二階建切妻造本瓦葺で、外壁は軒まで漆喰塗塗込とし、南面窓に塗込の鎧庇を付す。東面に蔵前を設け良材を用いた縁で主屋と接続。戸口は観音開きの鉄扉とし、楣に亀甲の家紋を付す。道路の突当たりに建ち、景観の要となる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015037"},{"id":"00015040","register_sub_id":"101","register_pk":"529318","name":"市川家住宅（旧亀岡家別荘）南中門","kana":"いちかわけじゅうたく（きゅうおかめおかけべっそう）みなみちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区帝塚山西四丁目84-1他","lat":34.6171,"lng":135.49569167,"geo_status":"db","era":"大正後期／昭和後期改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"中門 木造、鉄板葺、間口1.2m、左右袖塀付","structure_material":"中門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0911","desc":"表門から主屋玄関への苑路南側に建ち、南庭の出入口となる鉄板葺の腕木門。左右に伏間瓦葺の袖塀を付す。柱や棟木、楣などに皮付丸太、正面桁になぐり仕上の面皮材を用い、両開板扉は桟唐戸風で上部に格狭間を飾る。苑路から来客を迎える軽快なつくりの門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015040"},{"id":"00007763","register_sub_id":"101","register_pk":"108744","name":"逸翁美術館旧本館","kana":"いつおうびじゅつかんきゅうほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府池田市建石町1965他","lat":34.82603822,"lng":135.43086182,"geo_status":"db","era":"昭和12／昭和32改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積438㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"27-0530","desc":"敷地の北東隅に、西に玄関を開いて建つ。２階に収蔵庫を設けるＲＣ造２階建、建築面積４３８㎡。スペイン瓦型をした銀灰色の瓦を葺く。２階壁面にはハーフティンバーの柱や梁、斜材をあらわす。玄関は黄色の竜山石を壁に貼り、上部の２階には四葉形飾りが並ぶ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007763"},{"id":"00007766","register_sub_id":"101","register_pk":"108747","name":"逸翁美術館旧本館正門","kana":"いつおうびじゅつかんきゅうほんかんせいもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府池田市建石町1965他","lat":34.82621126,"lng":135.43025472,"geo_status":"db","era":"江戸後期／昭和11移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"27-0533","desc":"敷地の西辺北隅に位置する。桁行９．９ｍ梁間３．５ｍ、木造平屋建、入母屋造桟瓦葺の長屋門。中央に間口４．２ｍの門口を開き、両開戸を吊り、両脇に潜戸を設ける。腰下見板張の白漆喰壁で、庇付出格子窓を付ける。北側を守衛室、南側の畳敷を宿直室とした。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007766"},{"id":"00007767","register_sub_id":"101","register_pk":"108748","name":"逸翁美術館旧本館塀","kana":"いつおうびじゅつかんきゅうほんかんへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府池田市建石町1965他","lat":34.82621396,"lng":135.43076283,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、総延長47m","structure_material":"鉄筋コンクリート造","registered":"2009.08.07(平成21.08.07)","register_no":"27-0534","desc":"旧本館玄関の壁面を北へ延長させて北庭を囲む塀と、北側道路に面する塀などからなり、総延長４７ｍ。厚さ０．２ｍの鉄筋コンクリート造で、高さ１．６～２．１ｍと高低差をもたせる。旧本館と同様の壁仕上げや色調の瓦を用い、デザインの統一を図っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007767"},{"id":"00007765","register_sub_id":"101","register_pk":"108746","name":"逸翁美術館即庵","kana":"いつおうびじゅつかんそくあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府池田市建石町1965他","lat":34.82577913,"lng":135.43088448,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"27-0531","desc":"旧本館の南東に接続し、南庭に面する。入母屋造桟瓦葺、軒先を銅板葺とする軽快な姿。三畳台目の茶室と、その二方にまわる四半瓦敷の椅子席からなる。トコと点前座が並び、天井は杉板網代張、土間は竹垂木の化粧屋根裏天井。一三の発想になる進歩的な茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007765"},{"id":"00007764","register_sub_id":"101","register_pk":"108745","name":"逸翁美術館費隠","kana":"いつおうびじゅつかんひいん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府池田市建石町1965他","lat":34.8259233,"lng":135.43089985,"geo_status":"db","era":"昭和19／昭和23・平成5移築","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.8㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"27-0532","desc":"南庭の南東隅に建つ。東西棟の切妻造銅板葺で、東面に庇を掛ける。柱は直径８～９㎝の丸材で、淡黄色の土壁とし、北面西端に躙口を設け、西面に花頭窓を穿ち、その上部に扁額を掲げる。二畳の茶室で、奥行の浅い室床を付ける。伝統的な雰囲気を有する茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007764"},{"id":"00003567","register_sub_id":"101","register_pk":"104557","name":"稲束家住宅土蔵","kana":"いなつかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府池田市綾羽1-2466","lat":34.82680414,"lng":135.42586731,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"27 － 0260","desc":"主屋座敷部の西方に中庭を介して南北棟で建つ。桁行３間，梁間２間規模，切妻造，本瓦葺の妻入２階建土蔵で，南妻面側に本瓦葺の蔵前をとり，座敷西南から西に延びる便所等に連絡する。座敷，中庭とともに商家奥向きの空間を構成する要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003567"},{"id":"00001838","register_sub_id":"101","register_pk":"102828","name":"井上良尚家住宅油蔵","kana":"いのうえよしなおけじゅうたくあぶらぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高石市綾園2-5-31","lat":34.51978527,"lng":135.4385468,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積42㎡","structure_material":"土蔵造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"27 － 0103","desc":"井上家の屋敷地の北東と南東には濠が廻っている。油蔵は屋敷地東隅の角地に建ち，米や油等の貯蔵に用いられていた。切妻造・本瓦葺で，腰を縦板張，上部を漆喰塗りとし，濠に面した平側にも荷揚げ用の戸口を設ける。小規模だが，しっかりとしたつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001838"},{"id":"00001837","register_sub_id":"101","register_pk":"102827","name":"井上良尚家住宅蔵","kana":"いのうえよしなおけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高石市綾園2-5-31","lat":34.51974493,"lng":135.43809262,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積43㎡","structure_material":"土蔵造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"27 － 0102","desc":"蔵は主屋の西，屋敷地西北面の中央に建つ。切妻造・本瓦葺で，街路に面した北西面は塀と合わせて高い縦板張，他は漆喰塗とし，東面に戸口を設ける。内部は中２階建で，道具蔵として什器などを納めた。通風等の高窓を設けるなど，用途に合わせたつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001837"},{"id":"00001835","register_sub_id":"101","register_pk":"102825","name":"井上良尚家住宅主屋","kana":"いのうえよしなおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高石市綾園2-5-31","lat":34.51980676,"lng":135.43822414,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦及び茅葺、建築面積268㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"27 － 0100","desc":"近世には代々市場村庄屋職を務めた家柄。主屋は敷地西半を占め，右の上手居室部が茅葺・平屋建，左の下手土間部が本瓦葺・つし２階建になる。古い部材もあるが，居室部が整った19世紀前期頃の完成とみられる。地域の旧家にふさわしい雄大な規模の民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001835"},{"id":"00001839","register_sub_id":"101","register_pk":"102829","name":"井上良尚家住宅茶室","kana":"いのうえよしなおけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高石市綾園2-5-31","lat":34.51980831,"lng":135.4384587,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"27 － 0104","desc":"茶室は主屋居室部の東に玄関を挟んで連続している。平屋建，切妻造・桟瓦葺で，平面はともに床・棚付の４畳半間と６畳間の２室からなり，縁や控え室を巧みに配している。床柱に面皮柱を用いるなど，全体を数寄屋風の意匠でよくまとめた茶室建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001839"},{"id":"00001836","register_sub_id":"101","register_pk":"102826","name":"井上良尚家住宅長屋門","kana":"いのうえよしなおけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高石市綾園2-5-31","lat":34.51961518,"lng":135.43822089,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"27 － 0101","desc":"長屋門は主屋の南に建っている。入母屋造・本瓦葺で，背面には出桁造で庇を設ける。中央を内開き板戸とし，左右は背面に戸口をもつ室とする。外壁は鼠漆喰塗と真壁造を併用し，正面左に出格子窓を設ける。屋敷正面の構えとして，地域の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001836"},{"id":"00000452","register_sub_id":"101","register_pk":"101442","name":"今戸家住宅","kana":"いまとけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府箕面市桜ヶ丘2-7-26","lat":34.82383742,"lng":135.45905851,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建，アスファルト葺，建築面積94㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"27 － 0033","desc":"大正時代に宅地開発されたこの地域の初期の住宅の一つ。和洋併用のスパニッシュ風の外観の建物で，設計は奥戸大蔵，施工あめりか屋。当時，バンガロー式の洋風建築を日本化したあめりか屋式といわれる洋式の住宅が流行したが，その好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000452"},{"id":"00007088","register_sub_id":"101","register_pk":"108070","name":"岩根家住宅奥座敷","kana":"いわねけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府富田林市五軒家2-1525-1","lat":34.510586,"lng":135.562424,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0463","desc":"主屋の西側に接続する。建築面積８８㎡、木造平屋建、入母屋造および切妻造桟瓦葺で、２室の続き座敷の南・北に廊下を配する。１５畳敷の座敷は良質なつくりの座敷飾りを備え、内庭に面して開く。欄間彫刻などの造作も丁寧な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007088"},{"id":"00010843","register_sub_id":"101","register_pk":"201678","name":"岩根家住宅籠塀","kana":"いわねけじゅうたくかんごべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府富田林市五軒家二丁目1525-1","lat":34.510409,"lng":135.562303,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造、瓦葺、延長45m、潜り戸付","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"27 ‐ 0641","desc":"南蔵から西蔵の隅まで、敷地南西面沿いに折曲りにのびる塀。切石谷積の石垣天端に伏せた葛石上に建ち、延長四五メートル、高さ一・八メートル、切妻造桟瓦葺である。外側は腰高に竪板を張り、外側小壁と内壁を漆喰塗とする。歴史的集落の街路景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010843"},{"id":"00007087","register_sub_id":"101","register_pk":"108069","name":"岩根家住宅主屋","kana":"いわねけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府富田林市五軒家2-1525-1","lat":34.510555,"lng":135.562561,"geo_status":"db","era":"江戸末期／大正前期増築改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0462","desc":"敷地中央に南面して建つ。建築面積１８０㎡、木造２階建、入母屋造桟瓦葺。東半は土間を基本として大型の竈を残し、西半は５間取の床上部で、南側に続き座敷を配する。当初は広い土間をもつ整形４間取とみられる。近世の大型農家の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007087"},{"id":"00010841","register_sub_id":"101","register_pk":"201676","name":"岩根家住宅茶室","kana":"いわねけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府富田林市五軒家二丁目1525-1","lat":34.510654,"lng":135.562402,"geo_status":"db","era":"昭和32頃","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積3.1㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"27 ‐ 0639","desc":"酒蔵南側の中庭に所在する茶室で、知足亭と号する。直径、高さとも約二メートルの酒樽に、放射状に丸太垂木を配して円錐形の檜皮屋根を葺く。内部に床を設けて対面に躙り口を開き、側壁に円窓を穿つ。酒樽の内装を茶室化した異色な形態をもつ、蔵元の茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010841"},{"id":"00010840","register_sub_id":"101","register_pk":"201675","name":"岩根家住宅西蔵","kana":"いわねけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府富田林市五軒家二丁目1525-1","lat":34.510635,"lng":135.562308,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"27 ‐ 0638","desc":"敷地西辺の中央に南北棟で建ち、酒蔵に接続する。桁行一三メートル梁間五・七メートル、切妻造桟瓦葺で、南東面に吹放しの下屋を廻らせる。西面は石垣上に建ち、腰高に竪板を張り、窓上に庇を通す。梁や下屋の軸組に丸太を使う。酒造場の景観を形成する酒蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010840"},{"id":"00010839","register_sub_id":"101","register_pk":"201674","name":"岩根家住宅南蔵","kana":"いわねけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府富田林市五軒家二丁目1525-1","lat":34.51034,"lng":135.562574,"geo_status":"db","era":"大正前期／昭和50頃改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造及び木造平屋建、瓦葺、建築面積91㎡","structure_material":"土蔵造及び木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"27 ‐ 0637","desc":"敷地南の通り沿いに建つ。桁行一八メートルの長い土蔵の西端に、庭に面して座敷を設ける。土蔵部の通り側は漆喰塗で腰を竪板張とし、敷地内側は吹放しの下屋に戸口を配す。座敷は四畳半を主とする茶室に縁を廻らす。集落景観に寄与すると共に庭園に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010839"},{"id":"00010842","register_sub_id":"101","register_pk":"201677","name":"岩根家住宅門屋","kana":"いわねけじゅうたくもんや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府富田林市五軒家二丁目1525-1","lat":34.510358,"lng":135.562752,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造及び木造平屋建、瓦葺、建築面積118㎡","structure_material":"土蔵造及び木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"27 ‐ 0640","desc":"敷地東面南端に南北棟で構える切妻造の長屋門。門の南を米蔵、北を松寿亭と呼ぶ座敷とする。米蔵は土蔵造で漆喰で塗込め、腰を竪板張とする。松寿亭は真壁造で腰は簓子下見板張とし、内部は六畳に床や付書院を備える。南蔵とともに風格ある表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010842"},{"id":"00009341","register_sub_id":"101","register_pk":"194134","name":"上田家住宅主屋","kana":"うえだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市東豊中町3-194","lat":34.80142187,"lng":135.48197591,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0550","desc":"丘陵上の住宅地に敷地北寄りに建つ。木造平屋建、建築面積一三四平方メートル、切妻造桟瓦葺である。東面の玄関脇に洋風の室内をもつ応接間を配し、西側の居室部は中廊下型で、南面に縁を廻らす。昭和初期における和洋併置式の郊外住宅の一典型を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009341"},{"id":"00009342","register_sub_id":"101","register_pk":"194135","name":"上田家住宅離れ","kana":"うえだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市東豊中町3-194","lat":34.80155274,"lng":135.48205086,"geo_status":"db","era":"昭和15年／平成6年増築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0551","desc":"主屋東側に建つ。木造二階建、建築面積五八平方メートル、入母屋造桟瓦葺で、下階の主屋側に入母屋屋根の玄関を構える。下階は外壁杉皮張で内部も数寄屋風意匠でまとめるが、上階は出窓を設けたサンルームを配し近代的なつくりとする。住宅地を眺望する離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009342"},{"id":"00009343","register_sub_id":"101","register_pk":"194136","name":"上田家住宅物置","kana":"うえだけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府豊中市東豊中町3-194","lat":34.80150277,"lng":135.48197353,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積5㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0552","desc":"主屋背面に建つ。木造平屋建、桁行三・〇メートル梁間一・五メートル、片流れ招き屋根付桟瓦葺である。東側の物入れ正面に出入口を開き、西寄り半間四方を便所とする。側背面は竪板張とし上部を大壁とする。東豊中住宅地における標準的な物置の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009343"},{"id":"00015041","register_sub_id":"101","register_pk":"529319","name":"梲家（旧角谷家住宅）主屋","kana":"うだつや（きゅうかどやけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市西成区玉出東一丁目20","lat":34.62861389,"lng":135.49571667,"geo_status":"db","era":"大正2年／昭和40年代増築、平成27年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積165㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0912","desc":"南海電鉄岸里玉出駅の南東に位置する町家。つし二階建切妻造桟瓦葺で、正面庇両脇に桟瓦葺の卯建壁を付し漆喰塗仕上とする。座敷は床と床脇、平書院を備え、玄関廻りは丸窓や木の葉形下地窓、吊床など設けた数寄屋風。重厚な外観が地域の歴史的景観に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015041"},{"id":"00003274","register_sub_id":"101","register_pk":"104264","name":"宇野家住宅主屋","kana":"うのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町17-17","lat":34.450779,"lng":135.357941,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積374㎡、土塀付","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0219","desc":"宇野家は江戸時代以来代々鋳物業を営んだ家柄である。紀州街道に面した広大な敷地の西北部に主屋他の居住部があり，他は鋳物工場を構える。主屋は安政の地震後に建築されたと伝える大規模な町家で，土間の豪壮な梁組や北側の座敷など内部も良く残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003274"},{"id":"00003279","register_sub_id":"101","register_pk":"104269","name":"宇野家住宅高塀","kana":"うのけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府貝塚市北町17-17","lat":34.45089134,"lng":135.35796637,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、延長7.3m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0224","desc":"敷地の西側正面にあって主屋と西土蔵を繋ぐ高塀。延長７．３ｍを６間に割り，腰下を竪板壁，腰上を土壁とし，桟瓦葺の屋根を上げる。北から３間目は腰板壁の取り外しが可能で，内側に片引戸があり，内部の庭園への入口となる。町家のファサードを整える要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003279"},{"id":"00003275","register_sub_id":"101","register_pk":"104265","name":"宇野家住宅茶室","kana":"うのけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府貝塚市北町17-17","lat":34.45078485,"lng":135.35820072,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0220","desc":"主屋東北の座敷に渡り廊下を介して接続する独立棟の茶室。住宅内にはこのほかに主屋北側の仏間北側に角屋で出る茶室がある。４畳半の茶室，水屋，勝手，待合，雪隠からなる。意匠も本格的で，良好な状態で維持されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003275"},{"id":"00003277","register_sub_id":"101","register_pk":"104267","name":"宇野家住宅西土蔵","kana":"うのけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府貝塚市北町17-17","lat":34.45091835,"lng":135.35802203,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0222","desc":"主屋から北側の前庭を隔てた敷地西北隅にある２階建，本瓦葺の土蔵。自家の衣装等を収めた衣装蔵である。東土蔵に比べると材料の様子が新しい。構造は桁行の地棟がなく，梁間方向の側柱頂部を繋ぐ水平梁で棟木を支える方式で東土蔵とは相違がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003277"},{"id":"00003276","register_sub_id":"101","register_pk":"104266","name":"宇野家住宅東土蔵","kana":"うのけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町17-17","lat":34.450714,"lng":135.358124,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0221","desc":"主屋後方の庭内，南東隅にある２階建，本瓦葺の土蔵。宇野家は願泉寺の狂言方に属し，薪能に使用する狂言衣装をこの蔵に預かっていた。２間に３間の標準規模で，小屋は地棟に登梁を両側から掛け渡す形式。主屋と同時期頃のものと思われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003276"},{"id":"00006423","register_sub_id":"101","register_pk":"107406","name":"江戸堀コダマビル","kana":"えどぼりこだまびる","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区江戸堀1-10-26","lat":34.689598,"lng":135.495407,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積111㎡、塔屋付","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2007.10.02(平成19.10.02)","register_no":"27 － 0429","desc":"間口７．９ｍの南北に長い敷地に北面道路から退いて建つ。鉄筋コンクリート造、地上３階地下１階建、塔屋付で、外観はスパニッシュスタイルとする。光庭を中核として、地階から屋上まで立体的なプランニングをなす。都市型住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006423"},{"id":"00010202","register_sub_id":"101","register_pk":"198035","name":"榎原家住宅主屋","kana":"えばらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市小曽根1-214-1","lat":34.763279,"lng":135.486039,"geo_status":"db","era":"江戸末期／平成12改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積271㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0599","desc":"敷地中央に南面し、入母屋造本瓦葺で下屋を廻らし、上部壁は塗込めて格子窓を穿つ。東端を広い土間とし、六間取の前列土間寄りの勘定場を張出して、繊細な格子をたてる。中の間前面に式台を構え、奥座敷に上質な座敷飾を備える。庄屋の格式を伝える大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010202"},{"id":"00010209","register_sub_id":"101","register_pk":"198042","name":"榎原家住宅外塀","kana":"えばらけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府豊中市小曽根1-214-1他","lat":34.76343027,"lng":135.48592384,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、総延長9.2m、潜付","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0606","desc":"敷地の北辺に並ぶ離れや土蔵群をつなぐ塀で、総延長九・二メートルを測る。切石積基礎に建つ切妻造桟瓦葺の形式になり、北面は腰高に竪板張目板打ちとし、南面は真壁造で要所を板壁とする。水禍に対する屋敷の保全を担った塀で、集落の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010209"},{"id":"00010204","register_sub_id":"101","register_pk":"198037","name":"榎原家住宅土蔵一","kana":"えばらけじゅうたくどぞう１","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市小曽根1-214-1他","lat":34.763413,"lng":135.486,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0601","desc":"敷地北辺の中央、離れの西隣に東西棟で建つ。土蔵造二階建、桁行四・七メートル梁間三・八メートル、切妻造本瓦葺で、南面に戸口を開いて庇を付け、北面に小窓を穿つ。外壁は漆喰塗で軒裏まで塗込め、腰高に竪板を張り、要所を黒漆喰塗として外観を引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010204"},{"id":"00010205","register_sub_id":"101","register_pk":"198038","name":"榎原家住宅土蔵二","kana":"えばらけじゅうたくどぞう２","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市小曽根1-214-1他","lat":34.763408,"lng":135.485919,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0602","desc":"敷地北辺、土蔵一と土蔵三の間に南北棟で建つ。土蔵造二階建、桁行六・八メートル梁間三・九メートル、切妻造本瓦葺で、東面を戸口として庇を付け、西面に小窓を穿つ。外壁は漆喰塗で鉢巻を廻らせ、腰高に竪板を張る。柱を密に立て、もと米蔵の名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010205"},{"id":"00010206","register_sub_id":"101","register_pk":"198039","name":"榎原家住宅土蔵三","kana":"えばらけじゅうたくどぞう３","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市小曽根1-214-1他","lat":34.763403,"lng":135.485838,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積31㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0603","desc":"敷地の北西隅に南北棟で建つ。土蔵造二階建、桁行四・九メートル梁間四・〇メートル、切妻造本瓦葺で、南東面に縁と下屋を廻らし、南面西寄りに渡廊下を付属する。外壁は漆喰塗で鉢巻を廻らせ、北西面は腰高に竪板を張る。旧家の屋敷構えを引立てる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010206"},{"id":"00010208","register_sub_id":"101","register_pk":"198041","name":"榎原家住宅庭門及び塀","kana":"えばらけじゅうたくにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府豊中市小曽根1-214-1","lat":34.76334585,"lng":135.48608803,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"庭門 木造、瓦葺、間口1.9m 塀 木造、瓦葺、総延長3.5m","structure_material":"庭門 木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0605","desc":"主屋背面と離れの間をつなぐ桟瓦葺の門と塀で、奥庭の東辺を間仕切る。北寄りに開く庭門は間口一・九メートルの腕木門で、南半を竪板壁とし、北半を板戸片引とする。塀は門より棟を落とし、竪板壁で内法上部を開放とする。離れや土蔵群とともに庭空間を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010208"},{"id":"00010203","register_sub_id":"101","register_pk":"198036","name":"榎原家住宅離れ","kana":"えばらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市小曽根1-214-1","lat":34.763393,"lng":135.486113,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0600","desc":"敷地北辺、主屋北側に建ち、入母屋造桟瓦葺で周囲に下屋を廻らし、背面は竪板張で出格子を付ける。西奥を八畳主室として座敷飾を設け、南西面に数寄屋を加味した縁を廻らせる。中の間の前面に玄関を構え、室境に透彫欄間をいれる。敷地背面の景観を整える離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010203"},{"id":"00010207","register_sub_id":"101","register_pk":"198040","name":"榎原家住宅露地門及び塀","kana":"えばらけじゅうたくろじもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府豊中市小曽根1-214-1","lat":34.76312875,"lng":135.48588869,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"露地門 木造、瓦葺、間口1.2m 塀 木造、瓦葺、総延長13m","structure_material":"露地門 木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0604","desc":"主屋の式台西端から南に塀をのばし、中ほどに腕木門形式の露地門を開く。門は切妻造桟瓦葺で方立間に扉を吊る。塀は、表側は上部を黒漆喰塗として要所に格子窓を配して下部を竪板張とし、裏側は刷毛引き仕上げとする。屋敷の主庭を画し、閑静な佇まいを醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010207"},{"id":"00015328","register_sub_id":"101","register_pk":"532452","name":"戎井家住宅主屋","kana":"えびすいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市平野区平野東二丁目41他","lat":34.62251944,"lng":135.55728611,"geo_status":"db","era":"明治後期／昭和7年頃・同42年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積209㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0939","desc":"環濠集落平野郷南東部の角地に建つ商家の主屋。つし二階建で角側を入母屋造、他方を切妻造。一階は出格子と駒寄を建て、二階は虫籠窓を三箇所開き出桁造の軒裏まで漆喰で塗込める。座敷床脇に皮付丸太の落掛など材を吟味。近代平野郷の景観を良く伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015328"},{"id":"00015329","register_sub_id":"101","register_pk":"532453","name":"戎井家住宅土蔵","kana":"えびすいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市平野区平野東二丁目43","lat":34.6225,"lng":135.55750278,"geo_status":"db","era":"昭和7年／令和３年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0940","desc":"主屋の背面に建つ家財蔵。土蔵造二階建切妻造本瓦葺で鉢巻を廻し螻羽を塗込める。西面戸口は下屋を付し、反りのある兜桁に梅鉢紋を飾り、掛子塗戸を開く。腰は七宝繋の海鼠壁、側背面は竪板張で水切を付す。主屋とともに通りの歴史的景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015329"},{"id":"00000416","register_sub_id":"101","register_pk":"101406","name":"遠藤家住宅（旧プレスビテリアンミッションハウス）","kana":"えんどうけじゅうたく（きゅうぷれすびてりあんみっしょんはうす）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区帝塚山西3-2-11","lat":34.61946313,"lng":135.49699394,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建，瓦葺，建築面積128㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"27 － 0028","desc":"建築当初の規模は延べ40坪ほどで，正面中央に玄関ポーチを起き，大きく開いた窓等からなる洋風住宅。内部は，中央に階段ホールを設け，大きな暖炉のある居間や２階の書斎などに特徴がある。設計はW.M.ヴォーリスで，もと宣教師館として建てられたといわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000416"},{"id":"00000450","register_sub_id":"101","register_pk":"101440","name":"近江岸家住宅","kana":"おおみぎしけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府堺市西区浜寺昭和町三丁351","lat":34.54139685,"lng":135.44580415,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建，瓦葺，建築面積239㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"27 － 0031","desc":"大正から昭和にかけて開発された別荘地に建てられた円熟期のヴォーリズ設計になる木造２階建で，スパニッシュ瓦葺，切妻造の住宅。内部は中廊下式で，洋間と和室が混用になる。２階の過半にも和座敷を設け，外観意匠は和洋併用となるのが特徴である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000450"},{"id":"00000451","register_sub_id":"101","register_pk":"132557","name":"近江岸家住宅外塀","kana":"おおみぎしけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市西区浜寺昭和町三丁351","lat":34.54126783,"lng":135.44552738,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石積塀，延長92.7m，門構2箇所附属","structure_material":"石積塀","registered":"1998.01.16(平成10.01.16)","register_no":"27 － 0032","desc":"主屋と一体的に造られた植込み付の巨石積の外塀。正面及び側面に主屋と同じくスパニッシュ風の様式を取り入れた門が開く。表門は，切妻屋根付の親柱に簡素だが洗練された意匠の縦板厚板貼の門扉が取り付く。和洋混在の外塀として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000451"},{"id":"00016414","register_sub_id":"101","register_pk":"536481","name":"大矢家住宅主屋","kana":"おおやけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府交野市星田3039他","lat":34.76471667,"lng":135.66870278,"geo_status":"db","era":"昭和14年頃／平成15年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"27 - 0953","desc":"ＪＲ星田駅南東の高台に位置する実業家の旧別荘。２階建の洋館の北に平屋建の和館を接続する。洋館南面の玄関ポーチは一階柱を擬木仕上とし、櫛形ペディメントに漆喰レリーフを飾る。和館は玄関や座敷など数寄屋風の意匠とし、内外ともに凝ったつくりの主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016414"},{"id":"00005890","register_sub_id":"101","register_pk":"106875","name":"岡田家住宅主屋","kana":"おかだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府吹田市千里山西5-40-4","lat":34.78110915,"lng":135.50270448,"geo_status":"db","era":"大正末期／昭和13増改造","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0388","desc":"住宅地開発会社の設計施工で，洋室付き，寄棟造，外観真壁造縦板張の住宅を，大阪三越住宅建築部技師で建築家の岡田孝男が，玄関ポーチ付き，切妻造，外観ラスモルタル塗等に増改造。『住宅』誌寄稿の改造記により当時の住宅改良の実践が窺え貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005890"},{"id":"00003289","register_sub_id":"101","register_pk":"104279","name":"岡本家住宅北蔵","kana":"おかもとけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-11","lat":34.4503449,"lng":135.35793682,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、スレート葺、建築面積99㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0234","desc":"岡本家の敷地北側に３棟並ぶ土蔵のうち東端の蔵で，東側は座敷に接続する。６間に２間の長い２階蔵であるが内部は一室で，南北面の２個所に出入口を持つ。中蔵とともに震災後やむなく本瓦から人造スレート葺に変更されたが，敷地の構成要素として評価できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003289"},{"id":"00003286","register_sub_id":"101","register_pk":"104276","name":"岡本家住宅座敷","kana":"おかもとけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府貝塚市北町18-11","lat":34.45030602,"lng":135.35799363,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積67㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0231","desc":"敷地の東北隅に建つ離れ座敷。１階の東半をダイニングキッチン等に改造し，昭和４０年代につし２階も改造しているが，なお，１階西半に端正な８畳の座敷（茶室）を残す。１階東半は南に角屋を出し，通り土間のほか茶室の待合いがあったという。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003286"},{"id":"00003287","register_sub_id":"101","register_pk":"104277","name":"岡本家住宅新蔵","kana":"おかもとけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-11","lat":34.45041823,"lng":135.35779672,"geo_status":"db","era":"安政4","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0232","desc":"岡本家の敷地北側に３棟並ぶ土蔵のうち西側の通り沿いにある２間に３間の規模を持つ本瓦葺の２階蔵。土蔵３棟はいずれも醸造用のものではなく道具等を治めた内蔵の性格を持つ。新蔵は南側妻中央の柱に打たれた棟札により安政４年の建築が明らか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003287"},{"id":"00003288","register_sub_id":"101","register_pk":"104278","name":"岡本家住宅中蔵","kana":"おかもとけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-11","lat":34.45038738,"lng":135.35783574,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造2階建、スレート葺、建築面積62㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0233","desc":"岡本家の敷地北側に３棟並ぶ土蔵のうち中央の蔵で，２間に３間の規模を持つ２階建。享保年間建築の伝えがあるが，安政期の新蔵よりも明らかに材料が古く，天保期の仏間がこの蔵を避けて建てられていることから，この伝えはほぼ妥当と思われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003288"},{"id":"00011536","register_sub_id":"101","register_pk":"210385","name":"奥野家住宅衣装蔵","kana":"おくのけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府枚方市春日元町二丁目273","lat":34.80134806,"lng":135.686739,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"27-0669","desc":"主屋の北側に建つ。方二間、土蔵造二階建、切妻造平入、置屋根形式。正面の下屋庇に縁を設ける。内部は一室で板壁とし、木柄が太く、二階床梁、棟木、母屋桁に大径の丸太材を用いる。外部は漆喰塗で腰板を張り、妻面は二重に鉢巻を廻らし、街路景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011536"},{"id":"00007266","register_sub_id":"101","register_pk":"108248","name":"奥野家住宅米蔵","kana":"おくのけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府豊中市中桜塚2-422-1","lat":34.7787828,"lng":135.46898372,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積64㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0495","desc":"敷地北西隅に建つ。桁行１２ｍ梁間５．３ｍと規模の大きい２階建土蔵。屋根は切妻造で、もと本瓦葺で鉄板仮葺とする。布石積基礎上に建ち、外壁の一部を竪板張とする。通り側の妻上部に、漆喰で作られた唐破風と一対の円窓を設けて、際立った外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007266"},{"id":"00011538","register_sub_id":"101","register_pk":"210387","name":"奥野家住宅米蔵","kana":"おくのけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府枚方市春日元町二丁目273","lat":34.80135,"lng":135.68660389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"27-0671","desc":"敷地の北西隅に東面して建つ。桁行三間、梁間二間、土蔵造平屋建、切妻造、桟瓦葺。正面出入口の庇は、軒裏まで塗り込める。内部は二室に間仕切り、真壁である。外壁は漆喰塗で腰板を張り、妻面には水切り庇を付け、良好な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011538"},{"id":"00007264","register_sub_id":"101","register_pk":"108246","name":"奥野家住宅主屋","kana":"おくのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市中桜塚2-422-1","lat":34.778595,"lng":135.469162,"geo_status":"db","era":"江戸後期／平成10改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積313㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0493","desc":"敷地のほぼ中央に南面して建つ。木造つし２階建で、内部は広い土間と、もと３列３行の九間取の床上部からなる。入母屋造桟瓦葺で、正面東寄りに緩い起りの入母屋屋根の表玄関を設け、南・西面には深い庇をめぐらす。大型の農家建築で、近世庄屋の風格を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007264"},{"id":"00011535","register_sub_id":"101","register_pk":"210384","name":"奥野家住宅主屋","kana":"おくのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府枚方市春日元町二丁目273","lat":34.80127,"lng":135.68672389,"geo_status":"db","era":"江戸末期／明治35年・昭和43年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積262㎡","structure_material":"木造平屋一部2階建","registered":"2017.05.02(平成29.05.02)","register_no":"27-0668","desc":"敷地北寄りに南面する。桁行九間、梁間五間の主体部の東面に仏間と座敷、背面に角屋を張り出す。西半の土間は広大で、床上は整形四間取を基本とし正面に式台玄関を設ける。増築の座敷も欄間意匠に変化を与えた上質な造り。北河内地方の上層農家の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011535"},{"id":"00007268","register_sub_id":"101","register_pk":"108250","name":"奥野家住宅新蔵","kana":"おくのけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府豊中市中桜塚2-422-1","lat":34.77831648,"lng":135.46926311,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0497","desc":"敷地東南隅に、南北棟で建つ。桁行６．３ｍ梁間４．５ｍ、土蔵造２階建、切妻造、置屋根形式の本瓦葺で、北妻面に出入口と庇を設ける。外壁は鉢巻の下まで竪板を高く張る。かつては北側に建つ離れ座敷と、蔵前を介して接続していた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007268"},{"id":"00007270","register_sub_id":"101","register_pk":"108252","name":"奥野家住宅中門","kana":"おくのけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市中桜塚2-422-1","lat":34.778564,"lng":135.468979,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口4.2m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0499","desc":"主屋の南西角と門長屋の間に建ち、門から主屋への動線と主屋前庭を区画する。屋根桟瓦葺とする潜り門で、全長４．２ｍのほぼ中央の１．９ｍに、両開板戸を吊る。柱は方柱で、腕木により軒を支持。壁は腰を竪板張とし、小壁を漆喰仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007270"},{"id":"00011537","register_sub_id":"101","register_pk":"210386","name":"奥野家住宅道具蔵","kana":"おくのけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市春日元町二丁目273","lat":34.80111611,"lng":135.68669889,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積27㎡","structure_material":"土蔵造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"27-0670","desc":"主屋の南側に北面して建つ。桁行三間半、梁間一間半、土蔵造平屋建、切妻造平入、置屋根形式。正面に半間の土庇を付ける。内部は一室で板張とする。西・南面に各一所窓を設ける。外部は漆喰塗で腰板を張る。妻面のみ鉢巻を一重に廻らし、敷地景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011537"},{"id":"00011539","register_sub_id":"101","register_pk":"210388","name":"奥野家住宅長屋門","kana":"おくのけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市春日元町二丁目273","lat":34.80112306,"lng":135.68656306,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"27-0672","desc":"敷地西面に位置する。桁行一〇間の長大な長屋門で、切妻造の南端一間を落屋根とする。内部は北側を土間とし、北端はもと厩。南側は二室で供部屋当時の棹縁天井が残る。外壁は敷地内は真壁造、街路側を大壁とし、せがい造で軒を深くとり重厚な表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011539"},{"id":"00007265","register_sub_id":"101","register_pk":"108247","name":"奥野家住宅西蔵","kana":"おくのけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府豊中市中桜塚2-422-1","lat":34.7786977,"lng":135.4689563,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0494","desc":"敷地西辺、通り沿いに位置する。桁行７．５ｍ梁間４．５ｍ、土蔵造２階建、切妻造桟瓦葺の置屋根で、北半部の屋根を一段高くする。東面には庇を付ける。丁寧に積んだ布石積基礎上に建ち、周囲を竪板張とし、要所に小窓を開けて、持送り付の庇を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007265"},{"id":"00014058","register_sub_id":"101","register_pk":"508318","name":"小倉家住宅門","kana":"おぐらけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市西区浜寺昭和町五丁579-5","lat":34.53869444,"lng":135.44490278,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、間口4.91m、左右袖塀付","structure_material":"鉄筋コンクリート造","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0834","desc":"敷地東辺に建つ鉄筋コンクリート造の表門で両脇に袖塀を付す。本柱上部に絵様付腕木を造り出し、軒桁を支え、屋根は切妻造銅板葺で棟に桟瓦を載せる。本柱間に開き戸を吊り、北脇に潜戸を設ける。本柱と袖柱は緑色のタイル貼で、和洋折衷の意匠とする門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014058"},{"id":"00014057","register_sub_id":"101","register_pk":"508317","name":"小倉家住宅洋館","kana":"おぐらけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府堺市西区浜寺昭和町五丁579-5","lat":34.53867778,"lng":135.44484444,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積65㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0833","desc":"堺市西部の浜寺住宅地に建つ洋館。Ｌ字形平面で一階は北西の玄関から広間兼階段室を通り、南の応接室に至る。二階は階段室の西と南に部屋を配する。庇やパラペットにスペイン瓦を用い、玄関アーチや二階窓に意匠を凝らすスパニッシュスタイルの上質な洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014057"},{"id":"00003291","register_sub_id":"101","register_pk":"104281","name":"尾食家住宅離れ","kana":"おめしけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町38-19","lat":34.451782,"lng":135.358353,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0236","desc":"尾食家は江戸時代貝塚寺内町で旅籠や干鰯商を営んだ有力商人である。離れは主屋西側の川沿いに接続し，西側は現在は撤去された土蔵に達する蔵前座敷であった。取り付きから主屋とほぼ同時代に建築されたと考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003291"},{"id":"00015330","register_sub_id":"101","register_pk":"532454","name":"貝塚寺内町まちや館（旧田中家住宅主屋）","kana":"かいづかじないちょうまちやかん（きゅうたなかけじゅうたくおもや）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府貝塚市北町461","lat":34.44890833,"lng":135.35831389,"geo_status":"db","era":"明治35年／令和4年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築面積62㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0941","desc":"願泉寺門前を横切る通りに東面する商家の主屋。つし二階建切妻造平入桟瓦葺で、一階は出格子と平格子を構え、二階は虫籠窓と出格子窓を開く。東を土間とした二列四室で座敷は床・床脇・書院を備えた上質なつくり。建ちの低い外観で通りの景観を形成する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015330"},{"id":"00001930","register_sub_id":"101","register_pk":"102920","name":"片桐棲龍堂洗い場","kana":"かたぎりせいりゅうどうあらいば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府堺市堺区西湊町3-1-16","lat":34.56746379,"lng":135.46435355,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0111","desc":"中ノ蔵東妻面から東ノ蔵西妻面にかけて架けられた木造，平家建，真壁造の上屋的建造物で，南面を吹放ちとし，煉瓦塀を建てて庭園との境界とする。内部は化粧小屋裏を表し，床は地元産の赤煉瓦を矢筈状に敷いて特徴ある空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001930"},{"id":"00001925","register_sub_id":"101","register_pk":"102915","name":"片桐棲龍堂主屋","kana":"かたぎりせいりゅうどうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区西湊町3-1-16","lat":34.5674661,"lng":135.46421417,"geo_status":"db","era":"文化年間","year":1810,"year_source":"estimated","year_min":1804,"year_max":1817,"year_label":"文化年間","structure":"木造2階建、瓦葺、建築面積127㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0106","desc":"紀州街道より一本東側の中筋と阪堺電気軌道阪堺線に挟まれた敷地に位置する老舗の漢方薬局。主屋は，入母屋造，平入，つし２階の塗屋で，北寄り下手を土間とし，上手に７畳半と４畳半茶室，茶室の東奥に仏間と１０畳座敷を配し，土間の北方に旧店舗を繋げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001925"},{"id":"00001927","register_sub_id":"101","register_pk":"102917","name":"片桐棲龍堂中ノ蔵","kana":"かたぎりせいりゅうどうなかのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区西湊町3-1-16","lat":34.56743455,"lng":135.46427424,"geo_status":"db","era":"嘉永年間","year":1850,"year_source":"estimated","year_min":1848,"year_max":1854,"year_label":"嘉永年間","structure":"土蔵造2階建、瓦葺、建築面積12㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0108","desc":"主屋の東北方，東ノ蔵の西方に建つ。東ノ蔵と同様に嘉永年間の建造と伝える。桁行２間，梁行１間半規模のややたちの高い標準的造りの２階建土蔵で，東西棟の切妻造，本瓦葺，平入とし，南面に観音扉を付けて蔵前をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001927"},{"id":"00001926","register_sub_id":"101","register_pk":"102916","name":"片桐棲龍堂東ノ蔵","kana":"かたぎりせいりゅうどうひがしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区西湊町3-1-16","lat":34.5674139,"lng":135.46439314,"geo_status":"db","era":"嘉永年間","year":1850,"year_source":"estimated","year_min":1848,"year_max":1854,"year_label":"嘉永年間","structure":"土蔵造平屋建、瓦葺、建築面積17㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0107","desc":"主屋の東方，薬草園に連なる藪内流庭園の中央北辺の境界をなす位置に建つ。桁行２間，梁行２間半規模の切妻造，本瓦葺，妻入の平屋建土蔵で，嘉永年間の建造と伝える。主屋に向けた西面に入口を設け，のちに蔵前を煉瓦敷に整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001926"},{"id":"00001928","register_sub_id":"101","register_pk":"102918","name":"片桐棲龍堂摩利支尊天神社廟","kana":"かたぎりせいりゅうどうまりしそんてんじんしゃびょう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区西湊町3-1-16","lat":34.56737507,"lng":135.46448897,"geo_status":"db","era":"文化11頃","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積2.3㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0109","desc":"敷地の東方，藪内流庭園の東北隅の一画に位置する。切妻造，桟瓦葺，妻入の土台建，真壁造小祠で，西面して建つ。内部に，一間社流造，千鳥破風・唐破風付き，板葺の本殿を納める。片桐棲龍堂の歴史の一端を窺い知ることのできる建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001928"},{"id":"00001931","register_sub_id":"101","register_pk":"102921","name":"片桐棲龍堂煉瓦塀","kana":"かたぎりせいりゅうどうれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府堺市堺区西湊町3-1-16","lat":34.56742469,"lng":135.46433537,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"煉瓦造、延長6.4m","structure_material":"煉瓦造","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0112","desc":"洗い場の南辺の境界をなす塀で，東ノ蔵南西隅から発し，ほぼ真西に向けて築造。煉瓦１枚厚，イギリス積で，煉瓦２２段に積み，上部を二五分迫り出して桟瓦葺，両流の小屋根を載せる。洗い場煉瓦敷とともに赤煉瓦発祥地のひとつとされる堺に相応しい工作物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001931"},{"id":"00014254","register_sub_id":"101","register_pk":"509644","name":"勝田家住宅主屋","kana":"かつたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市生野区小路東三丁目15-1他","lat":34.65884167,"lng":135.56125278,"geo_status":"db","era":"大正後期／昭和4年増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積252㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0845","desc":"街路沿いに建つ地主の町家で、元は前栽があり少し引いた表構えを形成する。間口十間半の切妻造桟瓦葺、前後に下屋を付す。北奥の十畳二間続きの角座敷等は銘木に凝った造り、北端にサンルームを配す。戦火を免れた希少な近代の大型町家で往時の町並みを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014254"},{"id":"00011748","register_sub_id":"101","register_pk":"210764","name":"要家住宅内蔵","kana":"かなめけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310他","lat":34.43751,"lng":135.353286,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0684","desc":"離れ書院の東側に位置し、南面で台所棟に接続する。桁行三間、梁間二間、土蔵造二階建、切妻造桟瓦葺。妻中央の柱を他より太くし、地棟を渡し登梁を架ける。内壁は真壁造で、窓を一階で東西に一所ずつ、二階で東に一所設ける。敷地内で最も古い蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011748"},{"id":"00011753","register_sub_id":"101","register_pk":"210769","name":"要家住宅内長屋門","kana":"かなめけじゅうたくうちながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310他","lat":34.437208,"lng":135.353487,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0689","desc":"表長屋門に直行して建ち表門と台所門を画す。切妻造本瓦葺で、中央に内門を開く。内門は間口二メートルで両開板戸を吊り、南に納屋、北に供部屋を配する。表書院前空間と主屋の玄関前空間を明瞭に区画するもので、類例のほとんどない貴重な内長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011753"},{"id":"00011746","register_sub_id":"101","register_pk":"210762","name":"要家住宅表書院","kana":"かなめけじゅうたくおもてしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310他","lat":34.437279,"lng":135.353182,"geo_status":"db","era":"江戸中期／平成16年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺一部瓦葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0682","desc":"主屋の西に接続する、御成のための書院。式台は二間半と間口が広く、北に玄関の間、次の間を並べ、八畳の座敷を西へ矩折れに配す。座敷は床、床脇、付書院を備え、格式ある構えながら、岸和田藩主が倹約を旨としたことに従い、長押を用いず簡素な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011746"},{"id":"00011752","register_sub_id":"101","register_pk":"210768","name":"要家住宅表長屋門","kana":"かなめけじゅうたくおもてながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310他","lat":34.437138,"lng":135.353538,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積139㎡","structure_material":"土蔵造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0688","desc":"敷地南面に建つ。桁行一八間と長大で切妻造本瓦葺。表書院への表門と主屋への台所門の二門を開く。表門は間口二・七メートルで両開板戸を吊り東側に潜戸を開く堂々たる構えで、御成のための居室や納屋、厩を配する。旧家の格式を今に伝える長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011752"},{"id":"00011749","register_sub_id":"101","register_pk":"210765","name":"要家住宅唐戸蔵","kana":"かなめけじゅうたくかねのとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310他","lat":34.4375,"lng":135.353432,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積11㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0685","desc":"主屋の北東に北面し、道蔵と東面で接する。桁行二間、梁間一間半、切妻造本瓦葺。内壁は板張とする。窓は二階の西に一所設けるのみで、扉口は外より片開き板戸、鉄板張板戸、格子戸を三重に建て込み強固な造り。扉口庇の持送りには繰形の装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011749"},{"id":"00011751","register_sub_id":"101","register_pk":"210767","name":"要家住宅道具蔵","kana":"かなめけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310他","lat":34.437565,"lng":135.35333,"geo_status":"db","era":"江戸末期／平成5年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、スレート葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0687","desc":"唐戸蔵と向かい合わせに南面する。桁行三間、梁間二間半、切妻造スレート葺で、南面と扉口の庇は本瓦葺。内壁は板張とし、小屋組は和小屋。窓は二階東西に一所ずつ設ける。唐戸蔵・道蔵と共にコの字の配置となり、敷地東方の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011751"},{"id":"00011756","register_sub_id":"101","register_pk":"210772","name":"要家住宅土塀","kana":"かなめけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310","lat":34.437646,"lng":135.353399,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、総延長222m、門付","structure_material":"土塀","registered":"2017.06.28(平成29.06.28)","register_no":"27-0692","desc":"広大な屋敷地を囲む塀。南西部の一角と表長屋門西側を除く総延長二二二メートルで、本瓦を葺く。西面には二間腕木門を開く。土塀は、中塗仕上げで、隅部では円弧を描いて連続し、優美な曲面を描く。庄屋の豪壮な屋敷構えを構成し景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011756"},{"id":"00011754","register_sub_id":"101","register_pk":"210770","name":"要家住宅中門","kana":"かなめけじゅうたくなかもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310他","lat":34.437137,"lng":135.353089,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積9.6㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0690","desc":"表書院の西に接続し、敷地表側と主庭とを画する。切妻造、本瓦葺で、西に腰掛待合と雪隠を付ける。門口は一・八メートルで、色土壁仕上げの瀟洒な造り。藩主の御成に備えて設けられたもので、格式を整え、屋敷地内の景観を特徴づける中門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011754"},{"id":"00011755","register_sub_id":"101","register_pk":"210771","name":"要家住宅庭門及び塀","kana":"かなめけじゅうたくにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310","lat":34.437157,"lng":135.353023,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"庭門 木造、瓦葺、間口1.2m 塀 土塀、瓦葺、総延長24m","structure_material":"庭門 木造","registered":"2017.06.28(平成29.06.28)","register_no":"27-0691","desc":"中門の西端から北へ延びる庭門と塀。庭門は腕木門で、片開戸を建て込み、上部には折枝を入れ数寄屋風意匠で飾る。庭門の南北に塀が延びる。塀は土塀で、南側が本瓦葺、北側が桟瓦葺と違える。主庭と奥庭を画し、屋敷地内後方の庭園景観を構成する門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011755"},{"id":"00011747","register_sub_id":"101","register_pk":null,"name":"要家住宅離れ書院","kana":"かなめけじゅうたくはなれしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310他","lat":34.437485,"lng":135.353195,"geo_status":"db","era":"元文3年（1738）","year":1738,"year_source":"db","year_min":1738,"year_max":1738,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0683","desc":"主屋の北に建つ内向きの書院。七畳の座敷と次の間、茶室等からなる。茶室は二畳台目で西に一畳の榑板張を設け踏込床と躙口の上がり口とする。座敷は狆潜り、付書院の窓を花頭形とし、釘隠や引手金具は七宝で、花狭間欄間など細部意匠を凝らし、華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011747"},{"id":"00011750","register_sub_id":"101","register_pk":"210766","name":"要家住宅道蔵","kana":"かなめけじゅうたくみちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市畠中二丁目310他","lat":34.437575,"lng":135.353426,"geo_status":"db","era":"江戸後期／平成8年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0686","desc":"敷地東辺中央に建つ。桁行七間、梁間三間、切妻造本瓦葺。内部は南から三間位置で間仕切り、二室とする。一階は板張で二階は真壁。扉口は猪目の繰形のある持送りで庇を受け、窓は二階のみとし東南面は格子窓を塗り込める。屋敷内の土蔵のうち最も大規模なもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011750"},{"id":"00014632","register_sub_id":"101","register_pk":"515174","name":"川田家住宅主屋","kana":"かわだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目59","lat":34.67194722,"lng":135.560925,"geo_status":"db","era":"江戸後期／昭和3年頃・同27年頃・同60年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺一部鉄板葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0876","desc":"旧深江村の集落北辺に位置する旧家の主屋。文化二年の新家に際して購入した、入母屋造平入茅葺（鉄板仮葺）、食違い四間取型の農家建築。土間戸口の脇に出格子窓を設け、式台玄関を構え、座敷と次の間境は差鴨居で区切る。近世の標準的な民家として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014632"},{"id":"00014633","register_sub_id":"101","register_pk":"515175","name":"川田家住宅離れ","kana":"かわだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目59","lat":34.67193333,"lng":135.56100556,"geo_status":"db","era":"明治前期／昭和33年・同37年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0877","desc":"旧深江村の集落北辺にある旧家の離れ。幕末から明治に村役を務めるに際して建てた客間棟。切妻造妻入桟瓦葺の南北棟で、南北面に庇を付す。内部は平書院床構え付座敷で長押を巡らす。近世から明治に至る家柄と住居の発展を示し、座敷庭と共に屋敷構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014633"},{"id":"00006032","register_sub_id":"101","register_pk":"107017","name":"川中家住宅主屋","kana":"かわなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市今米1-4-38","lat":34.681599,"lng":135.625793,"geo_status":"db","era":"江戸中期／明治9改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0412","desc":"南北にやや長い敷地中央に南面して建つ。桁行１０間半，梁間５間の規模で，木造平屋建，入母屋造，茅葺とする。西側に２列に６室を並べ，東側に土間及び２室をとる。四方に下屋を廻し，瓦棟を載せる。伝統的な農家建築の外観をもち，歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006032"},{"id":"00006033","register_sub_id":"101","register_pk":"107018","name":"川中家住宅離れ","kana":"かわなかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府東大阪市今米1-4-38","lat":34.68170986,"lng":135.62580107,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0413","desc":"主屋の北側に東面して建つ。桁行５間，梁間２間半で，木造平屋建，入母屋造，桟瓦葺とする。６畳の座敷２室を東西に並べ，東側に式台玄関を設け，南側と西側に縁を廻す。伝統的意匠を基調とするが，床の間形式や縁のガラス欄間など近代の要素がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006033"},{"id":"00014876","register_sub_id":"101","register_pk":"519136","name":"河野家住宅裏土蔵西棟","kana":"かわのけじゅうたくうらどぞうにしとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市内田町三丁目236","lat":34.44813611,"lng":135.452525,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0903","desc":"衣装や布団を収納する土蔵。敷地北西隅に南面して建つ２階建切妻造平入、置屋根形式の本瓦葺で、南面中央に戸口、北面二階に小窓を二箇所開ける。各階板敷で１階は２室、２階は１室とし、小屋組は登梁形式。窓少なく閉鎖的な土蔵で敷地北西の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014876"},{"id":"00014877","register_sub_id":"101","register_pk":"519137","name":"河野家住宅裏土蔵東棟","kana":"かわのけじゅうたくうらどぞうひがしとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市内田町三丁目236","lat":34.44816667,"lng":135.45260278,"geo_status":"db","era":"江戸末期／明治後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積26㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0904","desc":"裏土蔵西棟の東に建つ家財蔵。平屋建切妻造、本瓦葺の置屋根形式の東西棟で、南に戸口を二箇所開け、桟瓦葺の下屋を付す。外壁は漆喰塗仕上、軒に鉢巻を廻らし、東妻は腰を海鼠壁とする。内部は２室で各室板敷とする。重厚な外観で敷地北面の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014877"},{"id":"00014878","register_sub_id":"101","register_pk":"519138","name":"河野家住宅裏門","kana":"かわのけじゅうたくうらもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市内田町三丁目236-1","lat":34.44815278,"lng":135.45282778,"geo_status":"db","era":"江戸末期／明治後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0905","desc":"敷地東辺中央に建つ南北棟で、北は入母屋造、南は切妻造で本瓦葺。北妻に桟瓦葺下屋を付して門口とし両開板戸を吊り、西に潜戸を設ける。門口の南は東寄りに便所と牛屋を配し、西寄りは門口から主屋へ至る通路とする。通りに面して旧家の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014878"},{"id":"00014875","register_sub_id":"101","register_pk":"519135","name":"河野家住宅表土蔵","kana":"かわのけじゅうたくおもてどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市内田町三丁目236","lat":34.44804722,"lng":135.45285833,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積13㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0902","desc":"敷地東面南寄りに建つ家財蔵。２階建切妻造平入の南北棟で、置屋根形式の本瓦葺とし、西に桟瓦葺の下屋を付す。外壁は漆喰塗仕上とし、東は腰を縦板張、西は海鼠壁で重厚にみせる。内部は各階板敷の一室とする。通りに沿って旧家の屋敷構えを形成する表土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014875"},{"id":"00014874","register_sub_id":"101","register_pk":"519134","name":"河野家住宅表門及び座敷","kana":"かわのけじゅうたくおもてもんおよびざしき","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市内田町三丁目236","lat":34.44795278,"lng":135.452875,"geo_status":"db","era":"江戸末期／明治後期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0901","desc":"敷地南東隅に東面する南北棟の長屋門で、西に東西棟の座敷を延ばし、全体に矩折れ平面を呈す。表門は中央を門口とし、北を物置、南を男部屋とする。座敷は六畳で南西に釣床と平書院を備え、北と西に縁を巡らす。通りに面した表門で、旧家の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014874"},{"id":"00014873","register_sub_id":"101","register_pk":"519133","name":"河野家住宅主屋","kana":"かわのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市内田町三丁目236","lat":34.44810278,"lng":135.45271111,"geo_status":"db","era":"嘉永4年(1851)／明治後期増築、昭和前期・同55年頃改修","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）及び瓦葺、建築面積237㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0900","desc":"松尾川沿いの農村集落に位置する旧家の屋敷。主屋は茅葺（鉄板仮葺）の大和棟で、東と西の落棟と南正面の下屋を本瓦葺とする。南面西寄りに式台を設け、内部は東に土間、西に前後二列八室を配する。式台や広い仏間など旧家の格式を備えた大規模で豪壮な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014873"},{"id":"00005479","register_sub_id":"101","register_pk":"106467","name":"岸田家住宅主屋","kana":"きしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市中小阪3-10-25","lat":34.65765622,"lng":135.58655955,"geo_status":"db","era":"江戸末期／明治5移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"27 － 0366","desc":"敷地の中央に南面して建つ。木造つし２階建で，切妻造，桟瓦葺とする。桁行７間，梁間４間の主屋の四周に下屋がつく。当初の北入を中古に南入に改めた。内部は西半に８畳４室の居室を整形に配す。土間は近年，北半に床を張るが，丁寧に改修された建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005479"},{"id":"00000698","register_sub_id":"101","register_pk":"101688","name":"岸本瓦町邸","kana":"きしもとかわらまちてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区瓦町1-2-1","lat":34.68622466,"lng":135.50919377,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積323㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"27 － 0042","desc":"東横堀川筋大手橋の西詰正面に位置する。住友工作部の笹川慎一の設計によるもので，竜山石による外装など住友ビルとの類似性が認められる。外観意匠は抑制されているが，室内意匠は密度が高く，昭和期大阪財界人の邸宅建築を代表する作品とすることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000698"},{"id":"00005286","register_sub_id":"101","register_pk":"106274","name":"北野家住宅主屋","kana":"きたのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区平野町四丁目22-1他","lat":34.68761731,"lng":135.49985342,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造3階建、瓦葺、建築面積45㎡","structure_material":"木造3階建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0340","desc":"近代大阪の中心，御堂筋近くの商業地にある。通りに面して建つ間口３間の木造３階建，切妻造，平入で，各階に庇をつけ，両側にうだつを設ける。正面外壁はタイル張，窓枠や軒の出桁廻りや蛇腹は銅板で覆う。防火性能を高めた近代商家の形式をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005286"},{"id":"00012579","register_sub_id":"101","register_pk":"367874","name":"北浜長屋","kana":"きたはまながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区北浜一丁目74","lat":34.691231,"lng":135.508118,"geo_status":"geocoded","era":"大正元年／昭和40年代・平成28年改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階地下1階建、瓦葺、建築面積108㎡","structure_material":"木造2階地下1階建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0752","desc":"土佐堀通に南面して建つ二軒長屋。正面一階は玄関上にペディメントを付け、二階は黒漆喰塗大壁で窓に観音扉、両端に袖卯建を設ける。土佐堀川沿いの背面は全面硝子窓とする。内部は前方に洋室、後方に和室を配する。開発進む市街地の貴重な歴史的添景である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012579"},{"id":"00013835","register_sub_id":"101","register_pk":"507797","name":"木村家住宅主屋","kana":"きむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市東本町二丁目47-7","lat":34.62846111,"lng":135.60345,"geo_status":"db","era":"江戸後期／昭和36年・同58年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積204㎡、塀付","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"27 － 0819","desc":"つし二階建切妻造桟瓦葺。北面し正面に下屋を付す。東寄りに玄関を設け、西は出格子を建てる。二階は格子窓を開ける。内部は東が土間、西が二列六室の床上部で、西列に正面から表座敷、中座敷、裏座敷を配する。河内木綿で財を成した商家の良質な町家遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013835"},{"id":"00005637","register_sub_id":"101","register_pk":"106625","name":"木村家住宅主屋","kana":"きむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市西区江之子島2-2-19","lat":34.68125557,"lng":135.48323085,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0368","desc":"木津川の左岸に位置し，大阪府の官舎として建設されたと伝える。下見板張の木造２階建の洋館で，東面１階中央に玄関を設け，瓔珞飾りをもつ切妻破風を付ける。内部は玄関北を洋室とするほかは和室で，１，２階西南に座敷を配する。大正期の洋風官舎として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005637"},{"id":"00013838","register_sub_id":"101","register_pk":"507800","name":"木村家住宅茶室","kana":"きむらけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府八尾市東本町二丁目47-7","lat":34.62848889,"lng":135.60331111,"geo_status":"db","era":"明治中期／明治後期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"27 － 0822","desc":"主屋の裏座敷から接続する。桁行一間半梁間二間半切妻造桟瓦葺。三畳と四畳半の茶室を並べる。北の三畳は点前座の台目の位置に炉を切る。南の四畳半は南に濡縁を付し大きな開口を開け、釣床や円窓など煎茶にふさわしい構えをつくる。屋敷地の点景を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013838"},{"id":"00013836","register_sub_id":"101","register_pk":"507798","name":"木村家住宅土蔵","kana":"きむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市東本町二丁目47-7","lat":34.62848889,"lng":135.60331111,"geo_status":"db","era":"文政8年(1825)","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積28㎡","structure_material":"土蔵造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"27 － 0820","desc":"主屋の西に廊下で接続する。桁行三間梁間二間、土蔵造二階建切妻造本瓦葺。漆喰で軒先まで塗込め、腰は竪板張。南に片引戸を建て戸前とし二階北に窓を開け庇まで塗込める。内部は一、二階とも一室で、小屋組は和小屋とする。主屋とともに通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013836"},{"id":"00013837","register_sub_id":"101","register_pk":"507799","name":"木村家住宅本蔵","kana":"きむらけじゅうたくほんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府八尾市東本町二丁目47-7","lat":34.62838056,"lng":135.60328889,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"27 － 0821","desc":"主屋の南西に建つ。桁行五間梁間二間、土蔵造二階建切妻造本瓦葺で、鉢巻まで漆喰で塗込め、妻に扇の鏝絵を飾る。腰は竪板張。東に廊下が取付き戸前とする。内部は一、二階とも一室で、太い牛梁が登梁を受ける。比較的大規模な土蔵が敷地西辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013837"},{"id":"00015047","register_sub_id":"101","register_pk":"529325","name":"旧井上家住宅内蔵","kana":"きゅういのうえけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.69366667,"lng":135.64937778,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0918","desc":"主屋の北西に東面して建つ、仏具などの家財蔵。二階建切妻造平入、置屋根形式の桟瓦葺で、外壁は漆喰塗仕上とし、軒廻りに鉢巻を廻らす。各階は一室の板敷で南辺に階段を置き、小屋は妻梁上の束で棟木と母屋を受ける。小規模ながら敷地西辺の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015047"},{"id":"00015050","register_sub_id":"101","register_pk":"529328","name":"旧井上家住宅裏米蔵","kana":"きゅういのうえけじゅうたくうらのうらぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.6938,"lng":135.64952222,"geo_status":"db","era":"江戸末期／昭和40年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0921","desc":"北蔵の東に南面して建つ米蔵。二階建切妻造平入、置屋根形式の本瓦葺。南面東寄りに戸口を開け、鉄板葺庇を付す。外壁は漆喰塗仕上で北壁は銅板張とする。各階一室の板敷で、小屋組は二重梁とし束で棟木を支持。北蔵と並び建つ姿が敷地北方の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015050"},{"id":"00015054","register_sub_id":"101","register_pk":"529332","name":"旧井上家住宅表米蔵","kana":"きゅういのうえけじゅうたくおもてのこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.69333333,"lng":135.64973611,"geo_status":"db","era":"江戸末期／大正前期・平成11年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0925","desc":"敷地南東隅、溜池に面して建つ米蔵。２階建切妻造平入桟瓦葺。外壁は漆喰塗仕上で軒裏を現す。北西に戸口を設けて庇を付し、一階は北東を板壁で区画した２室の板敷、二階は一室の板敷。南妻二箇所の窓上に漆喰塗込の鎧庇を付し、敷地南東景観の要となる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015054"},{"id":"00015055","register_sub_id":"101","register_pk":"529333","name":"旧井上家住宅表門","kana":"きゅういのうえけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.69333611,"lng":135.64959722,"geo_status":"db","era":"江戸末期／大正前期・昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0926","desc":"敷地南に通りより引込んで建つ長屋門。寄棟造平入桟瓦葺で東に落棟で納屋を接続。外壁は漆喰塗仕上、腰は簓子下見板張とする。中央東寄りを門口とし東に一室、西に三室を配し、門口に両開板扉を吊り両脇間に潜戸を設ける。旧家の風格を示す規模長大な長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015055"},{"id":"00015046","register_sub_id":"101","register_pk":"529324","name":"旧井上家住宅主屋","kana":"きゅういのうえけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.693575,"lng":135.64951111,"geo_status":"db","era":"天明4年（1784）／明治中期・昭和53年改修","year":1784,"year_source":"db","year_min":1784,"year_max":1784,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）一部瓦葺、建築面積273㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0917","desc":"生駒山西麓に位置する旧家の主屋。敷地中央に南面して建つ桁行一二間梁間五間半の大和棟で茅葺（銅板仮葺）とし、周囲に桟瓦葺下屋を廻らし、南東に井戸屋を突出する。東に広大な土間、西に居室を配して南西隅を床構えの座敷とする。桁行長大な大和棟の民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015046"},{"id":"00015049","register_sub_id":"101","register_pk":"529327","name":"旧井上家住宅北蔵","kana":"きゅういのうえけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.69381111,"lng":135.6494,"geo_status":"db","era":"江戸末期／大正2年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0920","desc":"敷地西辺北寄りに位置し、切石積の石垣上に建つ道具蔵。2階建切妻造平入で置屋根形式の桟瓦葺。南面東寄りを戸口とし、外壁は漆喰塗仕上で腰は竪板張。各階一室の板敷で西辺に階段を配す。小屋組は束立の和小屋。敷地内最大規模の土蔵で敷地外郭を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015049"},{"id":"00015051","register_sub_id":"101","register_pk":"529329","name":"旧井上家住宅北納屋","kana":"きゅういのうえけじゅうたくきたなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.69376944,"lng":135.64958889,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0922","desc":"裏米蔵の東に南面して建つ納屋。平屋建切妻造妻入桟瓦葺で、南面に戸口を開けて下屋を付し、上部に窓を開ける。外壁は漆喰塗仕上、腰は竪板張。内部は一室で西側を土間、東側を板敷とし、上部に束立の和小屋を現す。桁行長大な納屋で敷地北方の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015051"},{"id":"00015057","register_sub_id":"101","register_pk":"529335","name":"旧井上家住宅土塀","kana":"きゅういのうえけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市日下町七丁目802他","lat":34.69403889,"lng":135.64939167,"geo_status":"db","era":"江戸末期／明治中期・昭和前期・平成11年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長166m","structure_material":"土塀","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0928","desc":"表門から西、北へ延び、敷地の上段と下段の外周を廻り、東納屋に取り付く総延長一六六メートルの土塀。外壁を漆喰塗仕上、屋根を桟瓦葺とする。傾斜地に位置する広大な敷地の高低差に合わせ石垣高さを変えて周囲を廻り、旧家の風格ある屋敷景観をつくる土塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015057"},{"id":"00015048","register_sub_id":"101","register_pk":"529326","name":"旧井上家住宅中蔵","kana":"きゅういのうえけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.69376111,"lng":135.64933056,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0919","desc":"内蔵の北に位置し、調度品などの家財蔵。石垣上に東面して建つ二階建切妻造平入、置屋根形式の桟瓦葺。東面南寄りを戸口とし外壁漆喰仕上で腰竪板張。各階板敷で小屋は妻梁上の束で棟木と母屋を受け母屋に曲り材を使う。石垣上に屹立し敷地外郭の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015048"},{"id":"00015056","register_sub_id":"101","register_pk":"529334","name":"旧井上家住宅庭門及び土塀","kana":"きゅういのうえけじゅうたくにわもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市日下町七丁目802他","lat":34.69344444,"lng":135.64948889,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"庭門 木造、間口2.0m、北袖塀付 土塀 瓦葺、総延長21m","structure_material":"庭門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0927","desc":"主屋の南に広がる庭の東辺北寄りに建つ門とその南に延びる土塀。門は東面して建つ腕木門で切妻造桟瓦葺の周囲に銅板葺を廻らす。南半間を戸口とし板戸の引戸を入れ、北に袖塀を付す。土塀は漆喰塗仕上で桟瓦葺とし、表門から主屋への通路沿いの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015056"},{"id":"00015052","register_sub_id":"101","register_pk":"529330","name":"旧井上家住宅東納屋","kana":"きゅういのうえけじゅうたくひがしなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.69350833,"lng":135.64975,"geo_status":"db","era":"江戸末期／平成7年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造二階建、瓦葺、建築面積60㎡","structure_material":"木造二階建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0923","desc":"敷地東辺に建つ納屋。二階建切妻造平入桟瓦葺で西面に下屋を付し、外壁は漆喰塗仕上とする。一階は南北４室に仕切り、各室は土間で西面に半間の戸口を設け、二階は一室の板敷で物置。通りに面し、東門及び納屋の北に続き、長大な屋敷構えの一画を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015052"},{"id":"00015053","register_sub_id":"101","register_pk":"529331","name":"旧井上家住宅東門及び納屋","kana":"きゅういのうえけじゅうたくひがしもんおよびなや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府東大阪市日下町七丁目804","lat":34.69341667,"lng":135.64975,"geo_status":"db","era":"江戸末期／大正前期・平成7年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0924","desc":"敷地東辺に建つ長屋門。切妻造平入桟瓦葺、外壁漆喰塗仕上で腰は竪板張とする。中央北寄りを門口とし潜戸付の大戸を開く。北は踏込土間とした一室の畳敷で伴部屋、南を一室の土間で納屋とする。東納屋及び表米蔵と連続し、敷地東辺の長大な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015053"},{"id":"00005478","register_sub_id":"101","register_pk":"106466","name":"旧植田家住宅表門","kana":"きゅううえだけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府八尾市植松町1-20-2","lat":34.61627121,"lng":135.59835667,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2006.03.27(平成18.03.27)","register_no":"27 － 0365","desc":"敷地北西の道路に面して，土蔵一と控舎の間に設けられた門。切妻造，桟瓦葺である。桁行２間規模で，中央１間を門口として，両開の板戸を釣り込み，正面左手を潜戸とする。外壁は黒漆喰塗で，腰を簓子下見板張とする。道路側の景観を引き締めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005478"},{"id":"00005474","register_sub_id":"101","register_pk":"106462","name":"旧植田家住宅主屋","kana":"きゅううえだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市植松町1-20-2","lat":34.616123,"lng":135.598404,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積284㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"27 － 0361","desc":"長瀬川左岸の敷地に北西を正面として建つ。桁行２１ｍ，梁間１１ｍ規模の木造つし２階建である。屋根は切妻造，桟瓦葺で，正面下屋のみ本瓦葺とする。２階外壁は塗込で虫籠窓を設けている。内部は正面北を土間，南を床上の居室とし，２階にも座敷をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005474"},{"id":"00005475","register_sub_id":"101","register_pk":"106463","name":"旧植田家住宅土蔵一","kana":"きゅううえだけじゅうたくどぞういち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市植松町1-20-2","lat":34.61620279,"lng":135.59828542,"geo_status":"db","era":"江戸後期／明治中期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"27 － 0362","desc":"敷地北西の道路に面して建つ。桁行８間，梁間２間規模の土蔵造２階建で，切妻造，桟瓦葺の置屋根とする。外壁は白漆喰塗で１階部分を鉄板張とする。道路に面して１階に２箇所，２階に３箇所の窓を設ける。敷地正面側の景観を構成する中心的な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005475"},{"id":"00005476","register_sub_id":"101","register_pk":"106464","name":"旧植田家住宅土蔵二","kana":"きゅううえだけじゅうたくどぞうに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府八尾市植松町1-20-2","lat":34.61611367,"lng":135.59819342,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"27 － 0363","desc":"敷地北西の道路に面して，土蔵一の南西に並んで建つ。桁行６間，梁間２間規模の土蔵造２階建で，切妻造，桟瓦葺とする。敷地内側に庇をつけて蔵前とし，主屋と廊下で接続する。土蔵一との間は高塀で閉じている。敷地正面側の景観を構成する建物の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005476"},{"id":"00005477","register_sub_id":"101","register_pk":"106465","name":"旧植田家住宅控舎（番部屋）","kana":"きゅううえだけじゅうたくひかえしゃ（ばんべや）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府八尾市植松町1-20-2","lat":34.61629876,"lng":135.59838838,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積18㎡","structure_material":"土蔵造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"27 － 0364","desc":"敷地北西の道路に面して，土蔵一の北東に表門を介して接続する。桁行２間半，梁間２間規模の土蔵造平屋建で，切妻造，桟瓦葺とし，敷地内側に瓦葺庇をつけて戸口を開く。腰回りは敷地内面を竪板張り，外面は鉄板張りとする。内部は８畳間に床の間と物入がつく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005477"},{"id":"00011532","register_sub_id":"101","register_pk":"210482","name":"旧海野家住宅主屋","kana":"きゅううみのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉大津市助松町三丁目753-3","lat":34.51279694,"lng":135.41638194,"geo_status":"db","era":"昭和3年／昭和20年･同55年･平成27年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積137㎡","structure_material":"木造2階一部平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"27-0665","desc":"大正九年から開発された臨海住宅地に建つ。二階建で一階は応接間、書斎など洋室を配し、二階は座敷、茶室の和室とする。外観はスパニッシュを基調とし、内部は様々な様式を用いており、持送り等彫刻に独特の意匠が見られ、随所に施主の工夫が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011532"},{"id":"00011534","register_sub_id":"101","register_pk":"210484","name":"旧海野家住宅噴水泉","kana":"きゅううみのけじゅうたくふんすいせん","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府泉大津市助松町三丁目753-3","lat":34.51268806,"lng":135.41636111,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"コンクリート造、面積9.8㎡","structure_material":"コンクリート造","registered":"2017.05.02(平成29.05.02)","register_no":"27-0667","desc":"主屋南東の庭園の中心をなす。コンクリート造で、長方形の各辺中央を円弧状に膨らませた意匠とし、中央に花弁状のバードバスを据える。泉側面はモルタル掻き落としとし、上部は色漆喰仕上げで縁取やモールディングを施す。庭園の中心を成す噴水泉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011534"},{"id":"00011533","register_sub_id":"101","register_pk":"210483","name":"旧海野家住宅塀","kana":"きゅううみのけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉大津市助松町三丁目753-3","lat":34.51282389,"lng":135.416245,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"煉瓦造、総延長31m","structure_material":"煉瓦造","registered":"2017.05.02(平成29.05.02)","register_no":"27-0666","desc":"敷地西面の外塀と、外塀中央部より東に延びる壁泉、前庭東面の垣根から成る。煉瓦造でモルタル吹付け仕上げとする。外塀は彫り窪めた半円アーチを連続させた列柱を思わせる意匠が特徴的で、半円状の壁泉、アーチをもつ垣根とともに敷地景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011533"},{"id":"00016683","register_sub_id":"101","register_pk":"579167","name":"旧岡本家別邸主屋","kana":"きゅうおかもとけべっていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府貝塚市北町73","lat":34.450334,"lng":135.357758,"geo_status":"db","era":"江戸末期／明治前期増築、昭和前期・同60年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、スレート葺、建築面積73㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"27 - 0974","desc":"貝塚寺内町の御下筋に西面する旧町年寄所有の町家。つし二階建切妻造平入で元は本瓦葺。南は土間、北は一列に三室を配し、移築と伝わる増築の八畳は床、床脇、付書院を備え、欄間や釘隠は桐をモチーフとする。繊細な出格子の構えが寺内町の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016683"},{"id":"00016410","register_sub_id":"101","register_pk":"536477","name":"旧河﨑家住宅主屋","kana":"きゅうかわさきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市都島区網島町10-4","lat":34.69386111,"lng":135.52463056,"geo_status":"db","era":"昭和11年／令和6年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、瓦葺、建築面積203㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2025.11.17(令和7.11.17)","register_no":"27 - 0949","desc":"藤田邸跡公園の南に位置する実業家の旧宅。設計は木子七郎。鉄筋コンクリート造2階地下1階建、寄棟造の南東に切妻造を延ばす矩折の平面。緑釉スペイン瓦やアーチ窓などスパニッシュ様式を基調とし、軒を深く、和風要素を加味した意匠に木子の作風が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016410"},{"id":"00014504","register_sub_id":"101","register_pk":"513918","name":"旧木南家住宅主屋","kana":"きゅうきなみけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府枚方市三矢町28","lat":34.81263889,"lng":135.63907778,"geo_status":"db","era":"天保3年（1832）／令和元年改修","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造2階建、瓦葺、建築面積234㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0875","desc":"枚方宿の街道に面して所在する旧家の主屋。切妻造平入桟瓦葺、虫籠窓と出格子を見せる奥行一間半の表屋に、中庭を介して奥行三間居宅棟が平行する表屋造で、居室側で直交する座敷棟が繋ぐコの字平面。建築年代が明らかな江戸期の表屋造大型町家として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014504"},{"id":"00002645","register_sub_id":"101","register_pk":"103635","name":"旧是枝近有邸","kana":"きゅうこれえだちかありてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府堺市北区百舌鳥梅北町4丁185","lat":34.55871493,"lng":135.49716773,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造4階建、セメント瓦葺、建築面積52㎡","structure_material":"木造4階建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0166","desc":"木造モルタル塗４階建で，四方に急傾斜の袴腰の妻をみせ四方対称とし，中央に塔屋を載せたひときわ目立つ洋風意匠の外観が特徴。２層分のコリント式の柱で支えたベランダや角を丸く処理した壁面を用いる点も特異である。施工は村田元蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002645"},{"id":"00009657","register_sub_id":"101","register_pk":"194653","name":"旧田中家住宅乾蔵","kana":"きゅうたなかけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府富田林市本町423-4","lat":34.50218545,"lng":135.60026153,"geo_status":"db","era":"明治25／平成23改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0572","desc":"主屋座敷部の後方、小路沿いに南北棟で建つ土蔵。桁行四・九メートル梁間四メートル、土蔵造二階建、切妻造桟瓦葺である。外壁は、小路側や軒廻りは漆喰で塗込めるが、それ以外は真壁とし、一階部分は竪板張とする。二階を座敷とするなど特異な形式の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009657"},{"id":"00009656","register_sub_id":"101","register_pk":"194652","name":"旧田中家住宅主屋","kana":"きゅうたなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府富田林市本町423-4","lat":34.50209979,"lng":135.60031864,"geo_status":"db","era":"明治25／平成23移築・改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0571","desc":"道路から後退して南面するつし二階建町家で、東面切妻造、西面入母屋造、桟瓦葺とする。東側の土間の入口廻りを黒漆喰塗として竪板張とする。西側は整型四間取で前面に出格子を設け、座敷飾や欄間の意匠も洗練されている。富田林の町家の特徴を示す近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009656"},{"id":"00014644","register_sub_id":"101","register_pk":"515186","name":"旧中村家住宅主屋","kana":"きゅうなかむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市天見346","lat":34.39153889,"lng":135.59903611,"geo_status":"db","era":"江戸後期／明治30年代移築、昭和47年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺(鉄板仮葺)、建築面積147㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0888","desc":"県境紀見峠に程近い谷あいの農村旧家の主屋。茅葺（鉄板仮葺）の大和棟民家で土間側落棟とする。間取りは整形四間取、落棟を含め土間が平面の半分程度と広く、床構え付の座敷は六畳間でやや狭い。突止め溝や低い位置の煙返し梁等河内地方の古制溢れる民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014644"},{"id":"00014646","register_sub_id":"101","register_pk":"515188","name":"旧中村家住宅書斎及び渡廊下","kana":"きゅうなかむらけじゅうたくしょさいおよびわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天見346","lat":34.39163611,"lng":135.59885,"geo_status":"db","era":"明治30年代／昭和50年代改修","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0890","desc":"谷あいの農村旧家の屋敷北西角となる書斎と渡廊下。書斎は入母屋造桟瓦葺で、東面は土蔵に取付く。渡廊下は屋敷西面石垣に建つ。書斎西半の物置は元風呂、東半は六畳間、縁側と廊下は化粧屋根裏小舞打とする近代和風。庄屋屋敷の囲いとなり集落景観上重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014646"},{"id":"00014647","register_sub_id":"101","register_pk":"515189","name":"旧中村家住宅土蔵","kana":"きゅうなかむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府河内長野市天見346","lat":34.39163056,"lng":135.59892222,"geo_status":"db","era":"明治30年／昭和後期改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、スレート葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0891","desc":"谷あいの農村旧家の屋敷北側に位置する土蔵。切妻造平入、軒裏と母屋を丁寧に漆喰塗込とする置屋根形式で、元は瓦葺。各階板敷、内壁板張。小屋組は極太の松を二つ割りにした曲り梁。棟木に「大相撲四方柱用材」と墨書があり、地鎮や上棟に関する貴重な事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014647"},{"id":"00014648","register_sub_id":"101","register_pk":"515190","name":"旧中村家住宅門長屋","kana":"きゅうなかむらけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府河内長野市天見346","lat":34.39137778,"lng":135.59905278,"geo_status":"db","era":"明治32年／昭和前期改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0892","desc":"紀見峠に程近い谷あいの農村旧家の長大な門長屋。屋敷南面に門を開く。入母屋造桟瓦葺、真壁造腰板張。門口に板扉、脇に潜戸付。門の東室は土間付物入で与力窓を開ける。西室は三間続き床構え付座敷で表に出格子窓を構える。炉の痕が残り一時期養蚕に使用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014648"},{"id":"00014645","register_sub_id":"101","register_pk":"515187","name":"旧中村家住宅西座敷","kana":"きゅうなかむらけにしざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天見346","lat":34.39154167,"lng":135.59893611,"geo_status":"db","era":"明治30年代／昭和40年代改修","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0889","desc":"紀見峠に程近い谷あいの農村旧家の座敷棟。主屋の西に棟を連ねて接続する。入母屋造桟瓦葺、内部は付書院床構えの八畳続き間で、南北面に縁廊下を通し、主屋座敷を補完する。杉の絞り丸太床柱、板欄間など材に凝った造りで当時山林業を営んだ歴史を語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014645"},{"id":"00006696","register_sub_id":"101","register_pk":"107679","name":"旧羽室家住宅主屋","kana":"きゅうはむろけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市曽根西町4-59","lat":34.773293,"lng":135.462997,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階一部平屋建、瓦一部銅板葺、建築面積305㎡","structure_material":"木造2階一部平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0438","desc":"阪急宝塚線曽根駅西方の松籟園住宅地の東端に屋敷地を構える。桁行１２間規模、２階建で、８畳２室の続き座敷を中心に、西に応接室、東北に食堂と台所、東南に離れを配す。全体は簡略化された大壁造の和洋折衷住宅で、応接室等にモダニズム意匠を採り入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006696"}];
